    #[test]
    fn test_nvme_scheduler_recommendation() {
        let info = make_test_info();
        let recs = evaluate(&info).unwrap().recommendations;
        let sched_rec = recs.iter().find(|r| r.param.contains("scheduler"));
        assert!(sched_rec.is_some());
        assert_eq!(sched_rec.unwrap().recommended_value, "none");
        assert_eq!(sched_rec.unwrap().confidence, Confidence::High);
        assert_eq!(sched_rec.unwrap().category, Category::Performance);
    }

    #[test]
    fn test_swappiness_with_database() {
        let info = make_test_info();
        let recs = evaluate(&info).unwrap().recommendations;
        let swap_rec = recs.iter().find(|r| r.param == "vm.swappiness");
        // The rule reads the live swap table; a swapless runner gets no advice.
        if !swap_configured("/proc/swaps") {
            return;
        }
        assert!(swap_rec.is_some());
        assert_eq!(swap_rec.unwrap().recommended_value, "1");
    }

    #[test]
    fn test_thp_with_postgres() {
        let info = make_test_info();
        let recs = evaluate(&info).unwrap().recommendations;
        let thp_rec = recs.iter().find(|r| r.param.contains("hugepage"));
        assert!(thp_rec.is_some());
        assert_eq!(thp_rec.unwrap().recommended_value, "madvise");
    }

    #[test]
    fn test_thp_with_valkey() {
        // Valkey is the Linux Foundation's fork of Redis 7.2.4 - a drop-in
        // valkey-server binary with the same event-loop, memory-resident
        // cache workload, so every redis-server gate must count it. An
        // always-THP host running it must get the madvise recommendation.
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "valkey-server".to_string(),
        }];
        let recs = evaluate(&info).unwrap().recommendations;
        let thp_rec = recs
            .iter()
            .find(|r| r.param.contains("hugepage"))
            .unwrap_or_else(|| panic!("valkey-server must get the THP recommendation"));
        assert_eq!(thp_rec.recommended_value, "madvise");
    }

    #[test]
    fn test_thp_with_mongod_and_etcd() {
        // etcd is the coordination store of the same cache family and must get
        // the always->madvise recommendation; a streaming workload must not.
        // mongod must not either: MongoDB 8.0's default build asks for THP
        // `always` while the legacy allocator and 7.0 ask for it off, and the
        // host does not say which one runs.
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "mongod".to_string(),
        }];
        let recs = evaluate(&info).unwrap().recommendations;
        assert!(
            recs.iter()
                .all(|r| r.param != "transparent_hugepage/enabled"),
            "mongod's THP needs depend on its build"
        );
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "etcd".to_string(),
        }];
        let recs = evaluate(&info).unwrap().recommendations;
        let thp_rec = recs
            .iter()
            .find(|r| r.param.contains("hugepage"))
            .unwrap_or_else(|| panic!("etcd must get the THP recommendation"));
        assert_eq!(thp_rec.recommended_value, "madvise");
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "kafka".to_string(),
        }];
        let recs = evaluate(&info).unwrap().recommendations;
        assert!(
            recs.iter().all(|r| !r.param.contains("hugepage")),
            "a streaming workload is not latency-sensitive"
        );
    }

    #[test]
    fn test_thp_covers_the_search_workloads() {
        // The same "the gate and classify are two definitions of one thing"
        // agreement the sibling sweep established: classify's `has_search`
        // puts Elasticsearch and OpenSearch in the MemoryIntensive class, so
        // the gates that name their class advise them — swappiness through the
        // classification, and the vfs_cache_pressure list through the names it
        // swept in with zookeeper/consul — while eval_thp, the only place THP
        // is gated, stayed silent for them.
        for name in ["elasticsearch", "opensearch", "solr"] {
            let mut info = make_test_info();
            info.processes = vec![ProcessInfo {
                name: name.to_string(),
            }];
            assert_eq!(
                crate::profile::classify(&info),
                crate::profile::WorkloadType::MemoryIntensive,
                "{name} is the classifier's search workload"
            );
            let recs = evaluate(&info).unwrap().recommendations;
            let rec = recs
                .iter()
                .find(|r| r.param.contains("hugepage"))
                .unwrap_or_else(|| panic!("{name} must get the THP recommendation"));
            assert_eq!(rec.recommended_value, "madvise");
        }
    }

    #[test]
    fn test_thp_covers_the_classifier_latency_classes() {
        // The gate and `classify` are two definitions of one thing: the
        // workloads whose lookup stalls THP's collapse/split cause. classify
        // calls TiDB and TiKV (an OLTP database and its distributed KV store)
        // IoLatency, and ZooKeeper and Consul (the in-memory coordination-KV
        // family it groups with etcd) MemoryIntensive; the sibling rules that
        // share this gate (eval_swappiness, eval_dirty_ratio) take that verdict
        // directly, so those hosts were told to lower swappiness and
        // dirty_ratio while this list — the only place THP is gated — stayed
        // silent.
        for name in ["tidb-server", "tikv-server", "zookeeper", "consul"] {
            let mut info = make_test_info();
            info.processes = vec![ProcessInfo {
                name: name.to_string(),
            }];
            assert!(
                matches!(
                    crate::profile::classify(&info),
                    crate::profile::WorkloadType::IoLatency
                        | crate::profile::WorkloadType::MemoryIntensive
                ),
                "{name} must be a latency workload for the classifier"
            );
            let recs = evaluate(&info).unwrap().recommendations;
            let rec = recs
                .iter()
                .find(|r| r.param.contains("hugepage"))
                .unwrap_or_else(|| panic!("{name} must get the THP recommendation"));
            assert_eq!(rec.recommended_value, "madvise");
        }
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "make".to_string(),
        }];
        assert!(
            evaluate(&info)
                .unwrap()
                .recommendations
                .iter()
                .all(|r| !r.param.contains("hugepage")),
            "a build job is neither a database nor a cache"
        );
    }

    #[test]
    fn test_vfs_cache_pressure_covers_the_whole_service_gate() {
        // The whole gate list, not only the names a fix touched: the gate
        // forgot mongod (in every sibling db list), mariadbd (added to the
        // sibling gates by 73bdd5835/51913a79b but missed here), and
        // valkey-server (the Redis 7.2.4 fork the sweep of 0b55cba16 added
        // everywhere else). zookeeper/consul and opensearch are the
        // classifier's own peers of etcd and elasticsearch, which the same
        // sweep of the siblings never reached here. TiDB and TiKV are the
        // classifier's OLTP database and its distributed KV store (has_db ->
        // IoLatency): the sweep of the latency classes reached them in the
        // THP rule, but this list stayed silent for them. oracle is the last
        // OLTP database the sibling gates count that this list skipped, the
        // gap issue #7426 names. Every service the rule accepts must trigger
        // the recommendation, and a build job must not.
        for name in [
            "postgres",
            "mysqld",
            "mariadbd",
            "mongod",
            "clickhouse",
            "redis-server",
            "valkey-server",
            "memcached",
            "etcd",
            "zookeeper",
            "consul",
            "elasticsearch",
            "opensearch",
            "solr",
            "tidb-server",
            "tikv-server",
            "oracle",
        ] {
            let mut info = make_test_info();
            info.processes = vec![ProcessInfo {
                name: name.to_string(),
            }];
            let recs = evaluate(&info).unwrap().recommendations;
            let rec = recs
                .iter()
                .find(|r| r.param == "vm.vfs_cache_pressure")
                .unwrap_or_else(|| panic!("{name} must get the vfs_cache_pressure recommendation"));
            assert_eq!(rec.recommended_value, "50");
        }
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "make".to_string(),
        }];
        let recs = evaluate(&info).unwrap().recommendations;
        assert!(
            recs.iter().all(|r| r.param != "vm.vfs_cache_pressure"),
            "a build job is not a database or cache"
        );
    }

    #[test]
    fn test_thp_with_oracle() {
        // oracle is the one OLTP database is_database_present already counts
        // that this latency list skipped - the same cross-gate hole mongod
        // and etcd closed here. Oracle's own Linux guidance asks for THP off
        // (MOS 1557478.1), so an always THP host running it must get the
        // madvise recommendation.
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "oracle".to_string(),
        }];
        let recs = evaluate(&info).unwrap().recommendations;
        let thp_rec = recs
            .iter()
            .find(|r| r.param.contains("hugepage"))
            .unwrap_or_else(|| panic!("oracle must get the THP recommendation"));
        assert_eq!(thp_rec.recommended_value, "madvise");
    }

    #[test]
    fn max_map_count_advice_needs_a_readable_value() {
        // The rule fires below 262144, and read_sysctl_u64 maps an unreadable or
        // unparseable file to 0, which is below it: a masked or garbled proc
        // entry (a container's, typically) was reported as `current_value: "0"`
        // and answered with a raise on a host whose value was never read.
        let (_, high, others) = zero_switch_paths("max_map_count", b"262144\n");
        let low = high.with_file_name("low");
        std::fs::write(&low, b"65530\n").unwrap();
        let info = info_with_processes(&["java"]);
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_max_map_count_at(&info, &mut recs, path.to_str().unwrap());
            recs
        };

        let recs = advice(&low);
        assert_eq!(recs.len(), 1, "a readable 65530 is below the floor");
        assert_eq!(recs[0].current_value, "65530");
        assert!(advice(&high).is_empty(), "a readable 262144 is not");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable value is not 0",
                path.display()
            );
        }
    }

    #[test]
    fn max_map_count_counts_opensearch_like_its_elasticsearch_twin() {
        // The search pair the sibling gates already count (71000e2c8 and the
        // classifier's has_search): an OpenSearch-only host must get the same
        // advice an Elasticsearch host gets. The path-injectable form keeps
        // the assertion independent of the host's own /proc value.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_max_map_count_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let knob = dir.join("max_map_count");
        std::fs::write(&knob, "65530\n").unwrap();

        for name in ["java", "elasticsearch", "opensearch", "node", "nodejs"] {
            let mut info = make_test_info();
            info.processes = vec![ProcessInfo {
                name: name.to_string(),
            }];
            let mut recs = Vec::new();
            eval_max_map_count_at(&info, &mut recs, knob.to_str().unwrap());
            let rec = recs
                .iter()
                .find(|r| r.param == "vm.max_map_count")
                .unwrap_or_else(|| panic!("{name} must get the max_map_count advice"));
            assert_eq!(rec.recommended_value, "262144");
        }

        // The collector is not the runtime this gate is for.
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "node_exporter".to_string(),
        }];
        let mut recs = Vec::new();
        eval_max_map_count_at(&info, &mut recs, knob.to_str().unwrap());
        assert!(
            recs.iter().all(|r| r.param != "vm.max_map_count"),
            "node_exporter is not node"
        );

        // A host that already raised the knob is left alone.
        std::fs::write(&knob, "262144\n").unwrap();
        let mut info = make_test_info();
        info.processes = vec![ProcessInfo {
            name: "opensearch".to_string(),
        }];
        let mut recs = Vec::new();
        eval_max_map_count_at(&info, &mut recs, knob.to_str().unwrap());
        assert!(recs.is_empty(), "262144 is already the target");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// mongod warns "vm.max_map_count is too low" below twice its connection
    /// limit (SERVER-51233), which its stock 64000-file limit puts at 102400,
    /// above the kernel's 65530 default; the gate never counted it.
    #[test]
    fn max_map_count_counts_mongod() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_max_map_count_mongod_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let knob = dir.join("max_map_count");
        std::fs::write(&knob, "65530\n").unwrap();
        let advice = |name: &str| {
            let mut recs = Vec::new();
            eval_max_map_count_at(
                &info_with_processes(&[name]),
                &mut recs,
                knob.to_str().unwrap(),
            );
            recs
        };

        let recs = advice("mongod");
        assert_eq!(recs.len(), 1, "mongod must get the max_map_count advice");
        assert_eq!(recs[0].recommended_value, "262144");
        // The shell is a client, not the daemon.
        assert!(advice("mongosh").is_empty());

        std::fs::remove_dir_all(&dir).ok();
    }

    /// Cassandra's startup check (`StartupChecks.checkMaxMapCount`) warns below
    /// 1048575 under its default mmap disk access mode, so the JVM floor of
    /// 262144 is not enough for it: the rule stopped at 262144 on a host
    /// Cassandra still warns about.
    #[test]
    fn max_map_count_sizes_cassandra_to_its_own_check() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_max_map_count_cassandra_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let knob = dir.join("max_map_count");
        let advice = |procs: &[&str], value: &str| {
            std::fs::write(&knob, value).unwrap();
            let mut recs = Vec::new();
            eval_max_map_count_at(
                &info_with_processes(procs),
                &mut recs,
                knob.to_str().unwrap(),
            );
            recs.into_iter()
                .map(|r| r.recommended_value)
                .collect::<Vec<_>>()
        };

        // The JVM marker and the resolved service name, as read_processes
        // pushes them for a Cassandra node.
        let cassandra = ["java", "cassandra"];
        assert_eq!(advice(&cassandra, "65530\n"), ["1048575"]);
        assert_eq!(advice(&cassandra, "262144\n"), ["1048575"]);
        assert!(advice(&cassandra, "1048575\n").is_empty());
        // Other JVMs keep the existing floor.
        assert_eq!(advice(&["java"], "65530\n"), ["262144"]);
        assert!(advice(&["java"], "262144\n").is_empty());

        std::fs::remove_dir_all(&dir).ok();
    }

