    #[test]
    fn test_nvme_nr_requests() {
        let mut info = make_test_info();
        info.disks[0].nr_requests = Some(128);
        // Only an elevator that stays in place can take a deeper queue.
        info.disks[0].available_schedulers = vec!["mq-deadline".to_string()];
        let recs = evaluate(&info).unwrap().recommendations;
        let rec = recs.iter().find(|r| r.param.contains("nr_requests"));
        assert!(
            rec.is_some(),
            "Should recommend increasing nr_requests for NVMe"
        );
        assert_eq!(rec.unwrap().recommended_value, "1024");
        assert_eq!(rec.unwrap().confidence, Confidence::High);
    }

    #[test]
    fn test_nvme_nr_requests_skipped_under_none() {
        // Current `none`, or `none` recommended by the scheduler rule: either
        // way the queue ends at the hardware depth, so 1024 would hit EINVAL
        // or be reset by the elevator switch.
        for scheduler in ["none", "mq-deadline"] {
            let mut info = make_test_info();
            info.disks[0].scheduler = scheduler.to_string();
            info.disks[0].nr_requests = Some(127);
            let recs = evaluate(&info).unwrap().recommendations;
            assert!(
                !recs.iter().any(|r| r.param.contains("nr_requests")),
                "nr_requests cannot exceed the hardware depth under none (current {scheduler})"
            );
        }
    }

    /// `queue/nr_requests` fell back to 0 when it could not be read or parsed,
    /// and 0 sits below the 256 the rule raises an NVMe queue from: a masked
    /// or garbled attribute was reported as `current_value: "0"` and answered
    /// with a write on a disk whose depth was never read.
    #[test]
    fn nr_requests_advice_needs_a_readable_depth() {
        let dir = queue_attribute_tree(
            "nr_requests",
            ["nvme0n1", "nvme1n1", "nvme2n1", "nvme3n1", "nvme4n1"],
            "nr_requests",
            "128\n",
            &[("queue/scheduler", "[mq-deadline]\n")],
        );
        let mut info = make_test_info();
        info.disks = read_disk_info_from(&dir).expect("read the synthetic block tree");
        info.disks.sort_by(|a, b| a.name.cmp(&b.name));

        let mut recs = Vec::new();
        eval_nr_requests(&info, &mut recs);
        let advised: Vec<(&str, &str)> = recs
            .iter()
            .map(|r| (r.param.as_str(), r.current_value.as_str()))
            .collect();
        assert_eq!(
            advised,
            [("block/nvme0n1/nr_requests", "128")],
            "only the depth the disk reported is raised"
        );
        let depths: Vec<Option<u64>> = info.disks.iter().map(|d| d.nr_requests).collect();
        assert_eq!(depths, [Some(128), None, None, None, None]);

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn test_nvme_nr_requests_ok_when_high() {
        let mut info = make_test_info();
        info.disks[0].nr_requests = Some(1024);
        let recs = evaluate(&info).unwrap().recommendations;
        let rec = recs.iter().find(|r| r.param.contains("nr_requests"));
        assert!(
            rec.is_none(),
            "Should not recommend nr_requests when already high"
        );
    }

    #[test]
    fn bio_based_disk_gets_no_request_queue_knobs() {
        // The head device of an NVMe multipath host (`nvme0n1`, the one that
        // carries the filesystem) is allocated with blk_alloc_disk() — a
        // bio-based queue (v6.6 drivers/nvme/host/multipath.c:534, 7.3-rc6
        // :765). The kernel registers queue/scheduler, queue/nr_requests and
        // queue/rq_affinity in ONE attribute group that
        // blk_mq_queue_attr_visible() hides unless queue_is_mq() (v6.6
        // block/blk-sysfs.c:686-694; 7.3-rc6 :830-841, whose array is
        // introduced as "Request-based queue attributes that are not relevant
        // for bio-based queues"), so detection reads exactly the sentinels
        // below and none of the three files can be written. The per-path
        // devices that queue the I/O are blk-mq disks (blk_mq_alloc_disk(),
        // v6.6 drivers/nvme/host/core.c:3583, 7.3-rc6 :4264) and keep the
        // advice.
        let mut info = make_test_info();
        info.numa_nodes = 2;
        info.disks[0].scheduler = "unknown".to_string();
        info.disks[0].available_schedulers = Vec::new();
        info.disks[0].nr_requests = None;
        info.disks[0].rq_affinity = None;
        let recs = evaluate(&info).unwrap().recommendations;
        for knob in ["scheduler", "nr_requests", "rq_affinity"] {
            assert!(
                !recs.iter().any(|r| r.param.contains(knob)),
                "a bio-based queue exposes no {knob} file to write"
            );
        }
    }

    #[test]
    fn test_rq_affinity_only_on_numa() {
        // Driven through the path-injectable form with a plain command line and
        // a non-RT banner. `evaluate()` reads the running host's `/proc`, so on
        // a PREEMPT_RT or `threadirqs` host the forced-threading guard would
        // suppress the recommendation below and fail this assertion for a
        // reason that has nothing to do with NUMA.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_rq_affinity_numa_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let cmdline = dir.join("cmdline");
        std::fs::write(&cmdline, "BOOT_IMAGE=/vmlinuz root=/dev/sda1\n").unwrap();
        let version = dir.join("version");
        std::fs::write(
            &version,
            "Linux version 6.6.0 (gcc) #1 SMP PREEMPT_DYNAMIC\n",
        )
        .unwrap();
        let (cmdline, version) = (cmdline.to_str().unwrap(), version.to_str().unwrap());

        let mut info = make_test_info();
        info.numa_nodes = 1;
        info.disks[0].rq_affinity = Some(1);
        let mut recs = Vec::new();
        eval_rq_affinity_at(&info, &mut recs, cmdline, version);
        let rec = recs.iter().find(|r| r.param.contains("rq_affinity"));
        assert!(
            rec.is_none(),
            "Should not recommend rq_affinity on single NUMA"
        );

        info.numa_nodes = 2;
        info.disks[0].rq_affinity = Some(0);
        let mut recs = Vec::new();
        eval_rq_affinity_at(&info, &mut recs, cmdline, version);
        let rec = recs.iter().find(|r| r.param.contains("rq_affinity"));
        assert!(
            rec.is_some(),
            "Should recommend rq_affinity=1 on multi-NUMA NVMe"
        );
        assert_eq!(rec.unwrap().recommended_value, "1");
    }

    /// `queue/rq_affinity` fell back to 0 when it could not be read or parsed,
    /// and 0 is the switched-off migration this rule restores: a masked or
    /// garbled attribute was reported as `current_value: "0"` and answered
    /// with a write on a disk whose setting was never read.
    #[test]
    fn rq_affinity_advice_needs_a_readable_setting() {
        let dir = queue_attribute_tree(
            "rq_affinity",
            ["nvme0n1", "nvme1n1", "nvme2n1", "nvme3n1", "nvme4n1"],
            "rq_affinity",
            "0\n",
            &[("queue/scheduler", "[none] mq-deadline\n")],
        );
        let mut info = make_test_info();
        info.numa_nodes = 2;
        info.disks = read_disk_info_from(&dir).expect("read the synthetic block tree");
        info.disks.sort_by(|a, b| a.name.cmp(&b.name));
        // A plain command line and a non-RT banner, written after the block
        // tree is read so they do not show up as disks.
        let cmdline = dir.join("cmdline");
        std::fs::write(&cmdline, "BOOT_IMAGE=/vmlinuz root=/dev/sda1\n").unwrap();
        let version = dir.join("version");
        std::fs::write(
            &version,
            "Linux version 6.6.0 (gcc) #1 SMP PREEMPT_DYNAMIC\n",
        )
        .unwrap();

        let mut recs = Vec::new();
        eval_rq_affinity_at(
            &info,
            &mut recs,
            cmdline.to_str().unwrap(),
            version.to_str().unwrap(),
        );
        let advised: Vec<(&str, &str)> = recs
            .iter()
            .map(|r| (r.param.as_str(), r.current_value.as_str()))
            .collect();
        assert_eq!(
            advised,
            [("block/nvme0n1/rq_affinity", "0")],
            "only the setting the disk reported is restored"
        );
        let settings: Vec<Option<u64>> = info.disks.iter().map(|d| d.rq_affinity).collect();
        assert_eq!(settings, [Some(0), None, None, None, None]);

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn rq_affinity_only_restores_a_disabled_migration() {
        // rq_affinity=1 is the blk-mq default (QUEUE_FLAG_MQ_DEFAULT carries
        // QUEUE_FLAG_SAME_COMP) and already sends every completion that fired
        // outside the submitter's cache domain back to it, which covers the
        // cross-node case; 2 adds QUEUE_FLAG_SAME_FORCE, an IPI for completions
        // that share the cache domain too. Only 0 turns the migration off.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_rq_affinity_off_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let cmdline = dir.join("cmdline");
        std::fs::write(&cmdline, "BOOT_IMAGE=/vmlinuz root=/dev/sda1\n").unwrap();
        let version = dir.join("version");
        std::fs::write(
            &version,
            "Linux version 6.6.0 (gcc) #1 SMP PREEMPT_DYNAMIC\n",
        )
        .unwrap();
        let (cmdline, version) = (cmdline.to_str().unwrap(), version.to_str().unwrap());

        let mut info = make_test_info();
        info.numa_nodes = 2;
        for current in [1, 2] {
            info.disks[0].rq_affinity = Some(current);
            let mut recs = Vec::new();
            eval_rq_affinity_at(&info, &mut recs, cmdline, version);
            assert!(
                !recs.iter().any(|r| r.param.contains("rq_affinity")),
                "rq_affinity={current} already migrates cross-node completions"
            );
        }

        info.disks[0].rq_affinity = Some(0);
        let mut recs = Vec::new();
        eval_rq_affinity_at(&info, &mut recs, cmdline, version);
        let rec = recs.iter().find(|r| r.param.contains("rq_affinity"));
        assert_eq!(
            rec.map(|r| r.recommended_value.as_str()),
            Some("1"),
            "a disabled migration is restored to the default"
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn rq_affinity_skipped_when_irqs_are_forced_threaded() {
        // With interrupts forced into threads the completion is never migrated
        // to the submitting CPU: blk_mq_complete_need_ipi() returns false
        // before it reads the SAME_COMP/SAME_FORCE bits the write sets (v6.6
        // block/blk-mq.c:1163, 7.3-rc6 :1267), because the softirq it would
        // raise from the SMP call only wakes ksoftirqd. The advice is inert
        // there, and its reason promises exactly the migration the kernel
        // opts out of. Both ways into that mode show up in one file each:
        // `threadirqs` on the command line, `PREEMPT_RT` in the UTS banner.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_threaded_irqs_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let write = |name: &str, content: &str| {
            let path = dir.join(name);
            std::fs::write(&path, content).unwrap();
            path
        };
        let plain_cmdline = write("cmdline", "BOOT_IMAGE=/vmlinuz root=/dev/sda1\n");
        let threaded_cmdline = write("cmdline_threadirqs", "root=/dev/sda1 threadirqs\n");
        let plain_version = write(
            "version",
            "Linux version 6.6.0 (gcc) #1 SMP PREEMPT_DYNAMIC\n",
        );
        let rt_version = write(
            "version_rt",
            "Linux version 6.12.0 (gcc) #1 SMP PREEMPT_RT\n",
        );

        let mut info = make_test_info();
        info.numa_nodes = 2;
        info.disks[0].rq_affinity = Some(0);

        // Baseline: the migration is off and threads do not pin the
        // completion, so the advice stands.
        let mut recs = Vec::new();
        eval_rq_affinity_at(
            &info,
            &mut recs,
            plain_cmdline.to_str().unwrap(),
            plain_version.to_str().unwrap(),
        );
        assert!(
            recs.iter().any(|r| r.param.contains("rq_affinity")),
            "a migratable completion keeps the recommendation"
        );

        // Both forced-threading modes are inert.
        let cases = [
            (&threaded_cmdline, &plain_version, "threadirqs"),
            (&plain_cmdline, &rt_version, "PREEMPT_RT"),
        ];
        for (cmdline, version, label) in cases {
            let mut recs = Vec::new();
            eval_rq_affinity_at(
                &info,
                &mut recs,
                cmdline.to_str().unwrap(),
                version.to_str().unwrap(),
            );
            assert!(
                !recs.iter().any(|r| r.param.contains("rq_affinity")),
                "{label} pins the completion, so rq_affinity changes nothing"
            );
        }

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn quoted_boot_parameters_preserve_rq_affinity_decisions() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_cmdline_quotes_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let version = dir.join("version");
        std::fs::write(&version, "Linux version 6.6.0 #1 SMP PREEMPT_DYNAMIC\n").unwrap();
        let cmdline = dir.join("cmdline");
        let mut info = make_test_info();
        info.numa_nodes = 2;
        info.disks[0].rq_affinity = Some(0);
        let cases = [
            (r#"foo="a threadirqs b""#, true),
            (r#"foo="a threadirqs=0 b""#, true),
            (r#"foo="a -- b" threadirqs"#, false),
            (r#""threadirqs""#, false),
            (r#""threadirqs=0""#, false),
            (r#"foo="threadirqs""#, true),
            (r#"threadirqs="a -- b""#, false),
            ("-- threadirqs", true),
            ("threadirqs=0", false),
            ("root=/dev/sda1", true),
            ("'threadirqs'", true),
            (r#"foo="a \" threadirqs"#, false),
            ("\u{000b}threadirqs\t", false),
            (r#""--" threadirqs"#, true),
            ("--=value threadirqs", false),
        ];
        for (content, expect_advice) in cases {
            std::fs::write(&cmdline, content).unwrap();
            let mut recs = Vec::new();
            eval_rq_affinity_at(
                &info,
                &mut recs,
                cmdline.to_str().unwrap(),
                version.to_str().unwrap(),
            );
            assert_eq!(
                recs.iter().any(|r| r.param.contains("rq_affinity")),
                expect_advice,
                "{content:?}"
            );
        }
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn threadirqs_behind_the_init_separator_is_not_a_kernel_parameter() {
        // The kernel parses kernel parameters only up to a bare `--` and
        // passes the rest to init (v6.6 Documentation/admin-guide/
        // kernel-parameters.rst:12-16 and kernel/params.c:185-186; 7.3-rc6
        // :14-18 and :182-183), so a `threadirqs` token behind the separator
        // never reaches setup_forced_irqthreads() (v6.6 kernel/irq/manage.c:
        // 30-35) and never enables force_irqthreads(). The guard must not
        // drop the advice for a token the kernel ignores.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_cmdline_separator_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let write = |name: &str, content: &str| {
            let path = dir.join(name);
            std::fs::write(&path, content).unwrap();
            path
        };
        let version = write(
            "version",
            "Linux version 6.6.0 (gcc) #1 SMP PREEMPT_DYNAMIC\n",
        );

        let mut info = make_test_info();
        info.numa_nodes = 2;
        info.disks[0].rq_affinity = Some(0);

        // Behind the separator both spellings are init arguments, so the
        // migration is still off and the advice stands; before the separator,
        // and on a command line without one, behaviour is unchanged.
        let cases = [
            ("after", "root=/dev/sda1 ro -- threadirqs\n", true),
            ("after_value", "root=/dev/sda1 ro -- threadirqs=0\n", true),
            ("before", "root=/dev/sda1 threadirqs\n", false),
            ("none", "BOOT_IMAGE=/vmlinuz root=/dev/sda1 ro\n", true),
        ];
        for (name, content, expect_advice) in cases {
            let cmdline = write(&format!("cmdline_{name}"), content);
            let mut recs = Vec::new();
            eval_rq_affinity_at(
                &info,
                &mut recs,
                cmdline.to_str().unwrap(),
                version.to_str().unwrap(),
            );
            assert_eq!(
                recs.iter().any(|r| r.param.contains("rq_affinity")),
                expect_advice,
                "{name}: {content:?}"
            );
        }

        std::fs::remove_dir_all(&dir).ok();
    }

