    #[test]
    fn read_ahead_skips_devices_without_a_mount_target() {
        // A disk held by dm/md (a non-empty holders directory) is claimed
        // exclusively, so mounting a filesystem on it or on any partition of
        // it fails with -EBUSY (bd_may_claim(), v6.6 block/bdev.c:458-484),
        // and the stacked device computes its read-ahead from the stacked
        // limits rather than from the member's ra_pages (v6.6
        // drivers/md/dm-table.c:2029). A hidden disk (GENHD_FL_HIDDEN) is the
        // same dead end from the other side: no device number is registered
        // for it (v6.6 block/genhd.c:454, :508), so nothing can be mounted
        // there either. Both would make block/<disk>/read_ahead_kb promise a
        // change that never reaches a workload.
        for (disk_type, process, read_ahead_kb) in [
            (DiskType::HDD, "kafka", 128),
            (DiskType::NVMe, "postgres", 512),
        ] {
            for marker in ["holder", "hidden"] {
                let mut info = info_with_processes(&[process]);
                info.disks[0].disk_type = disk_type.clone();
                info.disks[0].read_ahead_kb = Some(read_ahead_kb);
                if marker == "holder" {
                    info.disks[0].holders = vec!["dm-0".to_string()];
                } else {
                    info.disks[0].hidden = true;
                }
                let mut recs = Vec::new();
                eval_read_ahead_kb(&info, &mut recs);
                assert!(
                    recs.is_empty(),
                    "a {disk_type:?} disk with a {marker} has no filesystem to read ahead for"
                );
            }

            // The same disk without either marker — an ordinary raw device, or
            // the NVMe multipath head carrying the filesystem — keeps its
            // advice.
            let mut info = info_with_processes(&[process]);
            info.disks[0].disk_type = disk_type.clone();
            info.disks[0].read_ahead_kb = Some(read_ahead_kb);
            let mut recs = Vec::new();
            eval_read_ahead_kb(&info, &mut recs);
            assert_eq!(
                recs.len(),
                1,
                "the mountable {disk_type:?} disk must keep its read-ahead advice"
            );
        }
    }

    /// An md array is a mountable device like any other: `/dev/md0` carries the
    /// filesystem, and `queue/read_ahead_kb` reaches the window it reads with —
    /// `setup_bdev_super()` takes `sb->s_bdi` from the block device's disk
    /// (v6.6 fs/super.c:1518) and the attribute sits in the general queue group
    /// (v6.6 block/blk-sysfs.c; only the mq-only group is hidden from bio-based
    /// queues). Nothing in md recomputes the window either: the only
    /// `disk_update_readahead()` caller under drivers/md is dm, and it runs on
    /// every table load (v6.6 drivers/md/dm-table.c:2029). Filtering `md*` out
    /// of the block-device read left an md host with no read-ahead advice at
    /// all, because the members are exactly the disks the `holders` gate
    /// excludes.
    #[test]
    fn read_ahead_advice_reaches_an_md_array() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_block_tree_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::remove_dir_all(&dir).ok();

        // An all-SSD array under the database, plus one entry of each shape the
        // filter must still drop. Only the array's attributes matter here.
        for name in ["md0", "dm-0", "loop0"] {
            let disk = dir.join(name);
            std::fs::create_dir_all(disk.join("queue")).expect("create queue");
            std::fs::create_dir_all(disk.join("holders")).expect("create holders");
            std::fs::write(disk.join("queue/rotational"), "0\n").expect("write rotational");
            std::fs::write(disk.join("queue/read_ahead_kb"), "256\n").expect("write read_ahead_kb");
            std::fs::write(disk.join("hidden"), "0\n").expect("write hidden");
        }

        let mut info = info_with_processes(&["postgres"]);
        info.disks = read_disk_info_from(&dir).expect("read the synthetic block tree");
        let names: Vec<&str> = info.disks.iter().map(|d| d.name.as_str()).collect();
        assert_eq!(
            names,
            ["md0"],
            "an md array is a disk; a dm member and a loop image are not: {names:?}"
        );
        assert_eq!(info.disks[0].disk_type, DiskType::SSD);

        let mut recs = Vec::new();
        eval_read_ahead_kb(&info, &mut recs);
        let rec = recs
            .iter()
            .find(|r| r.param == "block/md0/read_ahead_kb")
            .unwrap_or_else(|| panic!("the array carrying the database must be sized: {names:?}"));
        assert_eq!(rec.current_value, "256");
        assert_eq!(rec.recommended_value, "128");

        std::fs::remove_dir_all(&dir).ok();
    }

    /// A synthetic `/sys/block` tree with one disk per shape a queue
    /// attribute can take: `names[0]` holds `value`, then a garbled file, an
    /// empty file, a directory in the file's place, and no file at all. Every
    /// disk also carries `common`, so the rule under test reaches the read.
    fn queue_attribute_tree(
        tag: &str,
        names: [&str; 5],
        attribute: &str,
        value: &str,
        common: &[(&str, &str)],
    ) -> std::path::PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_{tag}_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::remove_dir_all(&dir).ok();
        for (index, name) in names.iter().enumerate() {
            let disk = dir.join(name);
            std::fs::create_dir_all(disk.join("queue")).expect("create queue");
            for (file, body) in common {
                std::fs::write(disk.join(file), body).expect("write a common attribute");
            }
            let path = disk.join("queue").join(attribute);
            match index {
                0 => std::fs::write(&path, value).expect("write the readable value"),
                1 => std::fs::write(&path, "garbage\n").expect("write a garbled value"),
                2 => std::fs::write(&path, "").expect("write an empty value"),
                3 => std::fs::create_dir_all(&path).expect("create a directory"),
                _ => {}
            }
        }
        dir
    }

    /// `queue/read_ahead_kb` fell back to 0 when it could not be read or
    /// parsed, and 0 sits below the 2048 KiB the rule raises a streaming HDD
    /// to: a masked or garbled attribute was reported as `current_value: "0"`
    /// and answered with a write on a disk whose window was never read.
    #[test]
    fn read_ahead_advice_needs_a_readable_window() {
        let dir = queue_attribute_tree(
            "read_ahead_kb",
            ["sda", "sdb", "sdc", "sdd", "sde"],
            "read_ahead_kb",
            "128\n",
            &[("queue/rotational", "1\n")],
        );
        let mut info = info_with_processes(&["kafka"]);
        info.disks = read_disk_info_from(&dir).expect("read the synthetic block tree");
        info.disks.sort_by(|a, b| a.name.cmp(&b.name));

        let mut recs = Vec::new();
        eval_read_ahead_kb(&info, &mut recs);
        let advised: Vec<(&str, &str)> = recs
            .iter()
            .map(|r| (r.param.as_str(), r.current_value.as_str()))
            .collect();
        assert_eq!(
            advised,
            [("block/sda/read_ahead_kb", "128")],
            "only the window the disk reported is sized"
        );
        let windows: Vec<Option<u64>> = info.disks.iter().map(|d| d.read_ahead_kb).collect();
        assert_eq!(windows, [Some(128), None, None, None, None]);

        std::fs::remove_dir_all(&dir).ok();
    }

    /// profile::classify calls a TiDB host io-latency — TiDB is an OLTP
    /// database and TiKV its distributed KV store — but this hand-rolled db
    /// list still skips both process names, so the host kept the default
    /// read-ahead window on the disks the rule is written for. Both names are
    /// in the sibling lists that take the classification (the THP gate, the
    /// swappiness/dirty_ratio rules); this gate is the only place the window
    /// is sized, so it stayed silent.
    #[test]
    fn tidb_and_tikv_gate_the_read_ahead_rule() {
        for name in ["tidb-server", "tikv-server"] {
            let mut info = info_with_processes(&[name]);
            info.disks[0].disk_type = DiskType::NVMe;
            info.disks[0].read_ahead_kb = Some(512);

            let mut recs = Vec::new();
            eval_read_ahead_kb(&info, &mut recs);
            let rec = recs
                .iter()
                .find(|r| r.param == "block/nvme0n1/read_ahead_kb")
                .unwrap_or_else(|| panic!("{name} must gate the read-ahead rule in"));
            assert_eq!(rec.recommended_value, "128");
        }
        // A workload outside the database class keeps the window it has.
        let mut info = info_with_processes(&["make"]);
        info.disks[0].disk_type = DiskType::NVMe;
        info.disks[0].read_ahead_kb = Some(512);
        let mut recs = Vec::new();
        eval_read_ahead_kb(&info, &mut recs);
        assert!(
            recs.iter()
                .all(|r| r.param != "block/nvme0n1/read_ahead_kb"),
            "a build job is not a database"
        );
    }

