    #[test]
    fn busy_read_requires_a_latency_sensitive_service_like_its_twin() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_busy_read_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let knob = dir.join("busy_read");
        std::fs::write(&knob, "0\n").unwrap();

        let base = || {
            let mut info = make_test_info();
            info.network = vec![NetInfo {
                name: "eth0".to_string(),
                speed_mbps: 10000,
            }];
            info
        };

        // A 10 GbE host without a latency-sensitive service (a backup or
        // file server) must not get busy_read: every blocking read on the
        // host would start spinning through a 50 us poll nobody asked for.
        let mut info = base();
        info.processes = vec![ProcessInfo {
            name: "rsync".to_string(),
        }];
        let mut recs = Vec::new();
        eval_busy_read_at(&info, &mut recs, knob.to_str().unwrap());
        assert!(
            recs.iter().all(|r| r.param != "net.core.busy_read"),
            "a 10 GbE host without a latency-sensitive service must not get busy_read"
        );

        // The twin rule's services on a 10 GbE link are the case both gates
        // exist for.
        for name in ["redis-server", "memcached", "nginx", "clickhouse"] {
            let mut info = base();
            info.processes = vec![ProcessInfo {
                name: name.to_string(),
            }];
            let mut recs = Vec::new();
            eval_busy_read_at(&info, &mut recs, knob.to_str().unwrap());
            let rec = recs
                .iter()
                .find(|r| r.param == "net.core.busy_read")
                .unwrap_or_else(|| panic!("{name} on 10 GbE must still get busy_read"));
            assert_eq!(rec.recommended_value, "50");
        }

        // The link half of the gate keeps working on its own.
        let mut info = base();
        info.network = vec![NetInfo {
            name: "eth0".to_string(),
            speed_mbps: 1000,
        }];
        info.processes = vec![ProcessInfo {
            name: "redis-server".to_string(),
        }];
        let mut recs = Vec::new();
        eval_busy_read_at(&info, &mut recs, knob.to_str().unwrap());
        assert!(
            recs.iter().all(|r| r.param != "net.core.busy_read"),
            "a 1 GbE link is not the busy-read case even for redis"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// busy_read gates on "the same services as the twin", so every service
    /// that earns a 10 GbE host the busy_poll advice must earn it busy_read
    /// too: the twin's list grew the OLTP databases and valkey after the
    /// busy_read gate copied it, and TiDB and TiKV (the classifier's OLTP
    /// database and its distributed KV store) are the remaining members of
    /// that database class - a TiDB host's per-query round-trip to its region
    /// store is the request-path shape this pair of rules exists for. oracle
    /// is the last member of that class (#7426), so the pair must fire for it
    /// as well.
    #[test]
    fn busy_read_counts_every_service_its_twin_counts() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_busy_twins_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let read_knob = dir.join("busy_read");
        let poll_knob = dir.join("busy_poll");
        std::fs::write(&read_knob, "0\n").unwrap();
        std::fs::write(&poll_knob, "0\n").unwrap();

        for name in [
            "redis-server",
            "valkey-server",
            "memcached",
            "nginx",
            "postgres",
            "mysqld",
            "mariadbd",
            "mongod",
            "clickhouse",
            "tidb-server",
            "tikv-server",
            "oracle",
            // The rest of the classifier's cache and search classes, and its
            // other proxies: the same request-path shape the first twelve
            // stand for.
            "etcd",
            "zookeeper",
            "consul",
            "elasticsearch",
            "opensearch",
            "httpd",
            "apache2",
            "envoy",
            "haproxy",
            "caddy",
        ] {
            let mut info = make_test_info();
            info.network = vec![NetInfo {
                name: "eth0".to_string(),
                speed_mbps: 10000,
            }];
            info.processes = vec![ProcessInfo {
                name: name.to_string(),
            }];
            let mut recs = Vec::new();
            eval_busy_poll_at(&info, &mut recs, poll_knob.to_str().unwrap());
            assert!(
                recs.iter().any(|r| r.param == "net.core.busy_poll"),
                "{name} is one of busy_poll's services"
            );
            eval_busy_read_at(&info, &mut recs, read_knob.to_str().unwrap());
            assert!(
                recs.iter().any(|r| r.param == "net.core.busy_read"),
                "{name} on 10 GbE gets busy_poll, so it must get its twin busy_read"
            );
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

