    /// `/proc/swaps` prints each area's path through `seq_file_path(swap,
    /// file, " \t\n\\")` (v6.6 mm/swapfile.c:2643), and `mangle_path` escapes
    /// only those four bytes: a swap file whose name is not UTF-8 is listed
    /// with its raw bytes, and the area is still configured.
    #[test]
    fn page_cluster_sees_a_swap_file_with_a_non_utf8_name() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_page_cluster_bytes_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let param = dir.join("page-cluster");
        std::fs::write(&param, b"3\n").unwrap();
        let swaps = dir.join("swaps-non-utf8");
        std::fs::write(
            &swaps,
            b"Filename\t\t\t\tType\t\tSize\t\tUsed\t\tPriority\n/swap\xff\xfe.img                          file\t\t1048572\t\t0\t\t-2\n",
        )
        .unwrap();
        assert!(std::str::from_utf8(&std::fs::read(&swaps).unwrap()).is_err());

        assert!(swap_configured(swaps.to_str().unwrap()));
        let mut recs = Vec::new();
        eval_page_cluster_at(
            &make_test_info(),
            &mut recs,
            param.to_str().unwrap(),
            swaps.to_str().unwrap(),
            &dir.join("no-sys-dev-block"),
            &dir.join("no-sys-class-block"),
        );
        assert!(
            recs.iter().any(|r| r.param == "vm.page-cluster"),
            "a configured swap area must keep the page-cluster advice"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn page_cluster_needs_a_swap_area_to_be_worth_setting() {
        // vm.page-cluster sizes the swap-in readahead window: v6.6 reads it
        // only from mm/swap_state.c (swapin_nr_pages / swapin_readahead / the
        // swap VMA readahead). On an SSD host with no swap area the
        // recommendation's promised IO saving cannot happen, so the rule must
        // stay quiet — the same "don't recommend a no-op" rule the
        // hardlockup_panic gate follows for a disabled NMI watchdog.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_page_cluster_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let param = dir.join("page-cluster");
        std::fs::write(&param, b"3\n").unwrap();
        // /proc/swaps always carries its header, so a header-only table means
        // no configured area.
        let header_only = dir.join("swaps-header-only");
        std::fs::write(
            &header_only,
            b"Filename\t\t\t\tType\t\tSize\t\tUsed\t\tPriority\n",
        )
        .unwrap();
        let with_swap = dir.join("swaps-active");
        std::fs::write(
            &with_swap,
            b"Filename\t\t\t\tType\t\tSize\t\tUsed\t\tPriority\n/dev/sda2                               partition\t16776188\t0\t\t-2\n",
        )
        .unwrap();
        let missing = dir.join("swaps-missing");

        let info = make_test_info();

        for swaps in [&header_only, &missing] {
            let mut recs = Vec::new();
            eval_page_cluster_at(
                &info,
                &mut recs,
                param.to_str().unwrap(),
                swaps.to_str().unwrap(),
                &dir.join("no-sys-dev-block"),
                &dir.join("no-sys-class-block"),
            );
            assert!(
                recs.is_empty(),
                "{}: no swap area means nothing to read in",
                swaps.display()
            );
        }

        let mut recs = Vec::new();
        eval_page_cluster_at(
            &info,
            &mut recs,
            param.to_str().unwrap(),
            with_swap.to_str().unwrap(),
            &dir.join("no-sys-dev-block"),
            &dir.join("no-sys-class-block"),
        );
        assert!(
            recs.iter().any(|r| r.param == "vm.page-cluster"),
            "an active swap area keeps the rule"
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn hardlockup_panic_advice_needs_a_readable_switch() {
        // The rule fires on 0 — a hard lockup does not panic — and
        // read_sysctl_u64 maps an unreadable or unparseable file to that same
        // 0: a masked or garbled proc entry (a container's, typically) was
        // reported as `current_value: "0"` and answered with a write of 1 on a
        // host whose switch was never read.
        let (off, on, others) = zero_switch_paths("hardlockup_panic_read", b"1\n");
        // No nmi_watchdog file: the rule's own gate, not the watchdog's.
        let nmi = off.with_file_name("no_nmi_watchdog");
        let info = make_test_info();
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_hardlockup_panic_at(
                &info,
                &mut recs,
                path.to_str().unwrap(),
                nmi.to_str().unwrap(),
            );
            recs
        };

        let recs = advice(&off);
        assert_eq!(
            recs.len(),
            1,
            "a readable 0 does not panic on a hard lockup"
        );
        assert_eq!(recs[0].current_value, "0");
        assert!(advice(&on).is_empty(), "a readable 1 does");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable switch is not 0",
                path.display()
            );
        }
    }

    #[test]
    fn hardlockup_panic_defers_to_the_watchdog_the_plan_disables() {
        // The perf rule writes kernel.nmi_watchdog = 0 on EVERY host that
        // reads 1 and runs a detector (eval_nmi_watchdog_at), and the
        // hardlockup detector is driven
        // by that watchdog: with the two entries in one plan the first write
        // disarms the detector the second one needs, so the High-confidence
        // security advice could never fire. The guard must therefore read the
        // watchdog the way the plan leaves it, not the way it found it.
        assert_eq!(
            hardlockup_panic_recommendation(0, Some(1)).map(|rec| rec.recommended_value),
            None,
            "the plan disables the watchdog, so the panic setting cannot fire"
        );
        assert_eq!(
            hardlockup_panic_recommendation(0, Some(0)).map(|rec| rec.recommended_value),
            None,
            "an already disabled watchdog is the case the guard always covered"
        );
        // A value the perf rule leaves alone, and a kernel without the knob:
        // the detector stays armed either way.
        assert_eq!(
            hardlockup_panic_recommendation(0, Some(2)).map(|rec| rec.recommended_value),
            Some("1".to_string())
        );
        assert_eq!(
            hardlockup_panic_recommendation(0, None).map(|rec| rec.recommended_value),
            Some("1".to_string())
        );
        // Already enabled: nothing to recommend.
        assert!(hardlockup_panic_recommendation(1, None).is_none());
    }

    #[test]
    fn page_cluster_gates_on_the_swap_areas_own_medium() {
        // The reason promises a saving "on an SSD", but this knob sizes the
        // readahead of the swap AREA, not of the disks the host happens to own:
        // a machine with an NVMe root and its swap on an HDD was told to set it
        // to 0, which turns one sequential read into one seek per page. The
        // area's own device decides.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_page_cluster_medium_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let param = dir.join("page-cluster");
        std::fs::write(&param, b"3\n").unwrap();
        let header = b"Filename\t\t\t\tType\t\tSize\t\tUsed\t\tPriority\n";
        let on_nvme = dir.join("swaps-nvme");
        std::fs::write(
            &on_nvme,
            [
                header.as_slice(),
                b"/dev/nvme0n1p2                           partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        let on_hdd = dir.join("swaps-hdd");
        std::fs::write(
            &on_hdd,
            [
                header.as_slice(),
                b"/dev/sdb2                                partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        // A file-backed area whose file no longer exists — an unlinked area is
        // still listed by /proc/swaps — has no device to stat, so no medium is
        // claimed for it. (The resolvable file case is asserted in
        // page_cluster_resolves_a_swap_files_medium_through_its_device, against
        // a synthetic device tree.)
        let on_a_file = dir.join("swaps-file");
        std::fs::write(
            &on_a_file,
            [
                header.as_slice(),
                b"/ktuner-nonexistent-swapfile               file\t\t16776188\t0\t\t-3\n",
            ]
            .concat(),
        )
        .unwrap();
        // Two near-misses the area must not resolve through: a partition of a
        // LONGER disk name that merely starts with a rotational disk's name,
        // and a partition suffix that is not one.
        let on_a_longer_name = dir.join("swaps-longer-name");
        std::fs::write(
            &on_a_longer_name,
            [
                header.as_slice(),
                b"/dev/sdaa2                               partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        let with_a_junk_suffix = dir.join("swaps-junk-suffix");
        std::fs::write(
            &with_a_junk_suffix,
            [
                header.as_slice(),
                b"/dev/sdb2bak                             partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        let whole_device = dir.join("swaps-whole-device");
        std::fs::write(
            &whole_device,
            [
                header.as_slice(),
                b"/dev/sdb                                 partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        // The HDD area next to an area whose path is not UTF-8: /proc/swaps
        // escapes only " \t\n\\", so the table as a whole is undecodable and
        // the rotational area must still be resolved through its raw bytes.
        let mixed_encoding = dir.join("swaps-non-utf8-sibling");
        std::fs::write(
            &mixed_encoding,
            [
                header.as_slice(),
                b"/dev/sdb2                                partition\t16776188\t0\t\t-2\n",
                b"/swap\xff\xfe.img                          file\t\t1048572\t\t0\t\t-3\n",
            ]
            .concat(),
        )
        .unwrap();
        assert!(std::str::from_utf8(&std::fs::read(&mixed_encoding).unwrap()).is_err());
        // Device-mapper areas: `dm-3` claims the rotational disk `sdb` (it is
        // in that disk's holders), `dm-4` claims the SSD `sdc`, `dm-9` claims
        // nothing the inventory reports, and `dm-30` is a different node from
        // the `dm-3` holder a prefix comparison would resolve.
        let on_a_mapper_over_hdd = dir.join("swaps-mapper-hdd");
        std::fs::write(
            &on_a_mapper_over_hdd,
            [
                header.as_slice(),
                b"/dev/dm-3                                partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        let on_a_mapper_over_ssd = dir.join("swaps-mapper-ssd");
        std::fs::write(
            &on_a_mapper_over_ssd,
            [
                header.as_slice(),
                b"/dev/dm-4                                partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        let on_an_unclaimed_mapper = dir.join("swaps-mapper-unclaimed");
        std::fs::write(
            &on_an_unclaimed_mapper,
            [
                header.as_slice(),
                b"/dev/dm-9                                partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();
        let on_a_longer_mapper_name = dir.join("swaps-mapper-longer-name");
        std::fs::write(
            &on_a_longer_mapper_name,
            [
                header.as_slice(),
                b"/dev/dm-30                               partition\t16776188\t0\t\t-2\n",
            ]
            .concat(),
        )
        .unwrap();

        // make_test_info carries one NVMe disk; add the rotational disks the
        // HDD fixtures' areas name (`sda` is the shorter name `sdaa2` merely
        // starts with), with the mapper node `dm-3` claiming `sdb`, and the SSD
        // `sdc` that `dm-4` claims.
        let mut info = make_test_info();
        for (name, holders) in [("sdb", vec!["dm-3".to_string()]), ("sda", vec![])] {
            info.disks.push(DiskInfo {
                name: name.to_string(),
                disk_type: DiskType::HDD,
                scheduler: "mq-deadline".to_string(),
                available_schedulers: vec!["none".to_string(), "mq-deadline".to_string()],
                nr_requests: Some(128),
                read_ahead_kb: Some(128),
                rq_affinity: Some(1),
                hidden: false,
                holders,
            });
        }
        info.disks.push(DiskInfo {
            name: "sdc".to_string(),
            disk_type: DiskType::SSD,
            scheduler: "mq-deadline".to_string(),
            available_schedulers: vec!["none".to_string(), "mq-deadline".to_string()],
            nr_requests: Some(128),
            read_ahead_kb: Some(128),
            rq_affinity: Some(1),
            hidden: false,
            holders: vec!["dm-4".to_string()],
        });

        for (swaps, expected, why) in [
            (&on_nvme, true, "the swap area is on the NVMe disk"),
            (&on_hdd, false, "the swap area is on the rotational disk"),
            (
                &whole_device,
                false,
                "a whole rotational device is not a partition",
            ),
            (
                &on_a_file,
                true,
                "a file area whose backing device cannot be resolved is left alone",
            ),
            (
                &on_a_longer_name,
                true,
                "sdaa2 is a partition of sdaa, not of sda",
            ),
            (
                &with_a_junk_suffix,
                true,
                "sdb2bak is not a partition of sdb",
            ),
            (
                &mixed_encoding,
                false,
                "a non-UTF-8 sibling name does not hide the HDD area",
            ),
            (
                &on_a_mapper_over_hdd,
                false,
                "the area's mapper node claims the rotational disk",
            ),
            (
                &on_a_mapper_over_ssd,
                true,
                "the area's mapper node claims the SSD disk",
            ),
            (
                &on_an_unclaimed_mapper,
                true,
                "a mapper node no reported disk holds claims no medium",
            ),
            (
                &on_a_longer_mapper_name,
                true,
                "dm-30 is a different node from the dm-3 holder",
            ),
        ] {
            let mut recs = Vec::new();
            eval_page_cluster_at(
                &info,
                &mut recs,
                param.to_str().unwrap(),
                swaps.to_str().unwrap(),
                &dir.join("no-sys-dev-block"),
                &dir.join("no-sys-class-block"),
            );
            let fired = recs.iter().any(|r| r.param == "vm.page-cluster");
            assert_eq!(fired, expected, "{why}: {}", swaps.display());
        }

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn page_cluster_resolves_a_swap_files_medium_through_its_device() {
        // A file-backed area prints a path, not a device name, so the
        // whole-disk inventory has nothing to match and its medium used to be
        // unknown — the advice went out even when the file sat on a rotational
        // disk. The medium is still knowable: stat() gives the device the
        // file's filesystem sits on, and /sys/dev/block/<major>:<minor> is the
        // block device that number belongs to; the device directory's
        // queue/rotational is the same flag the inventory reads, reached
        // through the partition directory when the number is a partition's.
        //
        // The synthetic tree plants the entry for this file's OWN device
        // number, so the code walks its real stat() -> major:minor ->
        // read_link path; the links are relative, as sysfs writes them.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_swap_file_medium_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("swapfile");
        std::fs::write(&file, b"swap").unwrap();
        let dev = std::fs::metadata(&file).unwrap().dev();
        let number = format!("{}:{}", libc::major(dev), libc::minor(dev));
        let swaps = dir.join("swaps");
        std::fs::write(
            &swaps,
            [
                b"Filename\t\t\t\tType\t\tSize\t\tUsed\t\tPriority\n".as_slice(),
                format!("{}\t\tfile\t\t1048572\t\t0\t\t-3\n", file.display()).as_bytes(),
            ]
            .concat(),
        )
        .unwrap();

        // The file's device number names a whole rotational device.
        let on_hdd = dir.join("sysdev-hdd");
        let hdd_disk = dir.join("devices/block/sdb");
        std::fs::create_dir_all(hdd_disk.join("queue")).unwrap();
        std::fs::write(hdd_disk.join("queue/rotational"), b"1\n").unwrap();
        std::fs::create_dir_all(&on_hdd).unwrap();
        std::os::unix::fs::symlink("../devices/block/sdb", on_hdd.join(&number)).unwrap();

        // The same number names a partition of a non-rotational disk.
        let on_a_partition = dir.join("sysdev-partition");
        let partition = dir.join("devices/block/nvme0n1/nvme0n1p2");
        std::fs::create_dir_all(&partition).unwrap();
        std::fs::write(partition.join("partition"), b"2\n").unwrap();
        std::fs::create_dir_all(dir.join("devices/block/nvme0n1/queue")).unwrap();
        std::fs::write(dir.join("devices/block/nvme0n1/queue/rotational"), b"0\n").unwrap();
        std::fs::create_dir_all(&on_a_partition).unwrap();
        std::os::unix::fs::symlink(
            "../devices/block/nvme0n1/nvme0n1p2",
            on_a_partition.join(&number),
        )
        .unwrap();

        // A tree with no entry for the number (the shape of a filesystem on a
        // device sysfs does not describe: tmpfs, overlayfs, a network mount).
        let no_entry = dir.join("sysdev-no-entry");
        std::fs::create_dir_all(&no_entry).unwrap();

        let info = make_test_info();
        let gate = |root: &std::path::Path| {
            swap_on_a_rotational_disk_at(
                &info,
                swaps.to_str().unwrap(),
                root,
                &dir.join("no-sys-class-block"),
            )
        };
        assert!(
            gate(&on_hdd),
            "a swap file on a rotational device must suppress the advice"
        );
        assert!(
            !gate(&on_a_partition),
            "a swap file on a partition of a non-rotational disk keeps the advice"
        );
        assert!(
            !gate(&no_entry),
            "a device number the tree has no entry for keeps today's advice"
        );

        // A file that no longer exists cannot be resolved either.
        std::fs::remove_file(&file).unwrap();
        assert!(
            !gate(&on_hdd),
            "an area whose file is gone keeps today's advice"
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    /// The usual LVM layout puts the physical volume on a partition, so the
    /// swap LV's mapper node holds `sdb2`, not `sdb`, and the holder link sits
    /// in the partition's directory rather than in the whole disk's `holders`.
    /// The inventory backed no disk for such an area and the gate let the
    /// "on an SSD" advice through for a swap LV on a rotational disk. The
    /// mapper node's own `slaves` directory names its members, and each member
    /// resolves against the inventory like the area itself.
    #[test]
    fn page_cluster_follows_a_mapper_swap_area_down_its_members() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_swap_mapper_members_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::remove_dir_all(&dir).ok();
        let class = dir.join("class-block");
        for (device, members) in [
            ("dm-1", &["sdb2"][..]),
            ("dm-2", &["dm-1"][..]),
            ("dm-5", &["vda2"][..]),
            ("dm-6", &["nvme0n1p3"][..]),
            ("dm-7", &[][..]),
            ("dm-8", &["dm-8"][..]),
        ] {
            let slaves = class.join(device).join("slaves");
            std::fs::create_dir_all(&slaves).unwrap();
            for member in members {
                std::fs::write(slaves.join(member), b"").unwrap();
            }
        }
        std::fs::create_dir_all(class.join("zram0")).unwrap();

        // make_test_info carries one NVMe disk; add a rotational disk and a
        // virtual disk, which the inventory types as an SSD by name whatever
        // its rotational flag says.
        let mut info = make_test_info();
        for (name, disk_type) in [("sdb", DiskType::HDD), ("vda", DiskType::SSD)] {
            let mut disk = info.disks[0].clone();
            disk.name = name.to_string();
            disk.disk_type = disk_type;
            disk.holders = vec![];
            info.disks.push(disk);
        }

        let gate = |area: &str| {
            let swaps = dir.join("swaps");
            std::fs::write(
                &swaps,
                format!(
                    "Filename\t\t\t\tType\t\tSize\t\tUsed\t\tPriority\n\
                     {area}                                partition\t16776188\t0\t\t-2\n"
                ),
            )
            .unwrap();
            swap_on_a_rotational_disk_at(
                &info,
                swaps.to_str().unwrap(),
                &dir.join("no-sys-dev-block"),
                &class,
            )
        };
        for (area, expected, why) in [
            ("/dev/dm-1", true, "an LV on a rotational disk's partition"),
            ("/dev/dm-2", true, "a mapper node stacked on that LV"),
            (
                "/dev/dm-5",
                false,
                "an LV on a virtual disk the inventory calls an SSD",
            ),
            ("/dev/dm-6", false, "an LV on an NVMe partition"),
            ("/dev/dm-7", false, "a mapper node with no listed member"),
            ("/dev/dm-8", false, "a member loop ends at the depth bound"),
            ("/dev/dm-9", false, "a device the tree does not list"),
            ("/dev/zram0", false, "a device with no slaves directory"),
        ] {
            assert_eq!(gate(area), expected, "{why}: {area}");
        }

        std::fs::remove_dir_all(&dir).ok();
    }

    /// A swap file on an LV resolves through its device number to the mapper
    /// node, and the mapper node's own `queue/rotational` is derived from its
    /// members: one virtio disk reporting rotational=1 makes the node read 1,
    /// while the inventory types that disk as an SSD by name. Reading the
    /// node's flag called such a file an HDD and withheld the advice the same
    /// host got for a swap partition on that disk; the node now resolves down
    /// its members like a `/dev` area.
    #[test]
    fn page_cluster_reads_a_swap_file_on_a_mapper_through_its_members() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_swap_file_mapper_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("swapfile");
        std::fs::write(&file, b"swap").unwrap();
        let dev = std::fs::metadata(&file).unwrap().dev();
        let number = format!("{}:{}", libc::major(dev), libc::minor(dev));
        let swaps = dir.join("swaps");
        std::fs::write(
            &swaps,
            [
                b"Filename\t\t\t\tType\t\tSize\t\tUsed\t\tPriority\n".as_slice(),
                format!("{}\t\tfile\t\t1048572\t\t0\t\t-3\n", file.display()).as_bytes(),
            ]
            .concat(),
        )
        .unwrap();

        // The file's device number names a mapper node whose own flag reads
        // rotational, the way dm derives it from a virtio member.
        let sys_dev_block = dir.join("sysdev");
        let node = dir.join("devices/virtual/block/dm-0");
        std::fs::create_dir_all(node.join("queue")).unwrap();
        std::fs::write(node.join("queue/rotational"), b"1\n").unwrap();
        std::fs::create_dir_all(&sys_dev_block).unwrap();
        std::os::unix::fs::symlink("../devices/virtual/block/dm-0", sys_dev_block.join(&number))
            .unwrap();

        let mut info = make_test_info();
        for (name, disk_type) in [("sdb", DiskType::HDD), ("vda", DiskType::SSD)] {
            let mut disk = info.disks[0].clone();
            disk.name = name.to_string();
            disk.disk_type = disk_type;
            disk.holders = vec![];
            info.disks.push(disk);
        }
        let gate = |member: Option<&str>| {
            let class = dir.join(format!("class-{}", member.unwrap_or("none")));
            std::fs::create_dir_all(class.join("dm-0/slaves")).unwrap();
            if let Some(member) = member {
                std::fs::write(class.join("dm-0/slaves").join(member), b"").unwrap();
            }
            swap_on_a_rotational_disk_at(&info, swaps.to_str().unwrap(), &sys_dev_block, &class)
        };
        assert!(
            !gate(Some("vda2")),
            "an LV on a virtual disk the inventory calls an SSD keeps the advice"
        );
        assert!(
            gate(Some("sdb2")),
            "an LV on a rotational disk's partition withholds it"
        );
        assert!(
            gate(None),
            "a node no member resolves keeps reading its own flag"
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn rmem_default_advice_needs_a_readable_value() {
        // The rule fires below 262144, and read_sysctl_u64 maps an unreadable or
        // unparseable file to 0, which is below it: a masked or garbled proc
        // entry (a container's, typically) was reported as `current_value: "0"`
        // and answered with a raise on a host whose value was never read.
        let (_, high, others) = zero_switch_paths("rmem_default", b"262144\n");
        let low = high.with_file_name("low");
        std::fs::write(&low, b"212992\n").unwrap();
        let mut info = make_test_info();
        info.network = vec![NetInfo {
            name: "eth0".to_string(),
            speed_mbps: 10000,
        }];
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_rmem_default_at(&info, &mut recs, path.to_str().unwrap());
            recs
        };

        let recs = advice(&low);
        assert_eq!(recs.len(), 1, "a readable 212992 is below the floor");
        assert_eq!(recs[0].current_value, "212992");
        assert!(advice(&high).is_empty(), "a readable 262144 is not");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable value is not 0",
                path.display()
            );
        }
    }

