    #[test]
    fn kernel_at_least_parses_release_suffixes() {
        assert!(kernel_at_least("6.8.0-40-generic", 4, 15));
        assert!(kernel_at_least("5.15.0-microsoft-standard-WSL2", 5, 0));
        // The boundary itself counts: FACK was removed in 4.15.
        assert!(kernel_at_least("4.15.0", 4, 15));
        assert!(!kernel_at_least("4.14.209", 4, 15));
        assert!(!kernel_at_least("3.10.0-1160.el7", 4, 15));
        assert!(!kernel_at_least("5.4", 6, 0));
        // Unparseable strings keep the caller's legacy behavior.
        assert!(!kernel_at_least("", 4, 15));
        assert!(!kernel_at_least("custom-kernel", 4, 15));
    }

    /// The knob's ceiling has been 31 since 6.3, and 31 is the value that
    /// reserves the LEAST of the window, so above it there is neither a value
    /// to fire on nor a direction that shrinks the reserve.
    #[test]
    fn tcp_app_win_advice_stops_where_the_ceiling_landed() {
        // 6.3 bounded the entry to [0, 31] ("tcp: restrict net.ipv4.tcp_app_win"),
        // so a larger value cannot be written there, and since 5.13 the u8 slot
        // cannot even hold one.
        assert!(tcp_app_win_recommendation(64, "6.3.0").is_none());
        assert!(tcp_app_win_recommendation(64, "6.6.87.2").is_none());
        assert!(tcp_app_win_recommendation(64, "6.2.16").is_some());
        assert!(tcp_app_win_recommendation(64, "5.4.0-150").is_some());
        // An unparseable version keeps the legacy behaviour.
        assert!(tcp_app_win_recommendation(64, "").is_some());
        // The value gate is unchanged: 31 is the top of the range.
        assert!(tcp_app_win_recommendation(31, "5.4.0").is_none());
        assert!(tcp_app_win_recommendation(0, "5.4.0").is_none());
        // Where it does fire, the reason must describe the reserve the kernel
        // computes (window >> tcp_app_win) rather than one over the value.
        let rec = tcp_app_win_recommendation(64, "5.4.0").expect("pre-6.3 kernels accept it");
        assert_eq!(rec.recommended_value, "31");
        assert!(
            !rec.reason.contains("1/64"),
            "the divisor is 2^tcp_app_win, not the value itself: {}",
            rec.reason
        );
    }

    #[test]
    fn laptop_mode_recommendation_gates_on_kernel_version() {
        // Through 6.19 the knob still defers writeback, so the advice holds.
        let rec = laptop_mode_recommendation(5, 64, "6.19.0")
            .expect("pre-7.0 kernels still consume the vm.laptop_mode knob");
        assert_eq!(rec.current_value, "5");
        assert_eq!(rec.recommended_value, "0");
        assert_eq!(rec.category, Category::Performance);
        assert!(laptop_mode_recommendation(5, 64, "5.15.0-microsoft-standard-WSL2").is_some());
        // 7.0 removed laptop mode (commit 64dd89ae01f2): the sysctl survives
        // only as a deprecated write-without-effect knob, so the advice would
        // promise less write delay that can no longer happen.
        assert!(laptop_mode_recommendation(5, 64, "7.0.0").is_none());
        assert!(laptop_mode_recommendation(5, 64, "7.3.0-rc6").is_none());
        // Already off, or not a big-memory host: no advice on any version.
        assert!(laptop_mode_recommendation(0, 64, "6.19.0").is_none());
        assert!(laptop_mode_recommendation(5, 8, "6.19.0").is_none());
    }

    #[test]
    fn laptop_mode_signed_read_survives_the_file_reader() {
        // The reader was the defect: the knob's handler accepts any int, a
        // negative value means the mode is ON, and every consumer tests its
        // truthiness. read_sysctl_u64 parsed "-1" to Err and fell back to 0 —
        // the value the guard reads as "already off" — so the rule stayed
        // quiet on exactly the host it warns about. The path-injectable form
        // keeps the branch assertable on any host.
        let path = std::env::temp_dir().join(format!("ktuner-laptop-mode-{}", std::process::id()));
        let path_str = path.to_str().unwrap();
        for (value, expect_rec) in [("-1", true), ("5", true), ("0", false)] {
            std::fs::write(&path, value).unwrap();
            let info = make_test_info();
            let mut recs = Vec::new();
            eval_laptop_mode_at(&info, &mut recs, path_str);
            let rec = recs.iter().find(|r| r.param == "vm.laptop_mode");
            assert_eq!(
                rec.is_some(),
                expect_rec,
                "value={value}: recommendation presence"
            );
            if let Some(rec) = rec {
                assert_eq!(rec.current_value, value);
                assert_eq!(rec.recommended_value, "0");
            }
        }
        std::fs::remove_file(&path).ok();
    }

