    #[test]
    fn suid_dumpable_reason_follows_the_mode_in_force() {
        // fs.rst's suid_dumpable table makes only mode 1 the leak case ("the
        // core dump is owned by the current user and no security is applied.
        // ... This is insecure as it allows regular users to examine the
        // memory contents of privileged processes"); mode 2 is "(suidsafe)"
        // and the kernel writes it as root, only to a pipe handler or a fully
        // qualified path, skipping a relative pattern outright
        // (fs/coredump.c). The mode-1 sentence must not be emitted on a mode-2
        // host, and the mode must still be advised off (0) in both cases.
        for (current, expects_rec) in [(0_u64, false), (1, true), (2, true)] {
            let rec = suid_dumpable_recommendation(current);
            assert_eq!(rec.is_some(), expects_rec, "value {current}");
            let rec = match rec {
                Some(rec) => rec,
                None => continue,
            };
            assert_eq!(rec.param, "fs.suid_dumpable");
            assert_eq!(rec.current_value, current.to_string());
            assert_eq!(rec.recommended_value, "0");
            assert_eq!(rec.category, Category::Security);
            if current == 2 {
                assert!(
                    !rec.reason.contains("泄露"),
                    "mode 2 is the controlled dump mode: {}",
                    rec.reason
                );
                assert!(
                    rec.reason.contains("root"),
                    "mode 2 names the privileged writer: {}",
                    rec.reason
                );
                assert!(
                    rec.reason.contains("管道处理器或绝对路径"),
                    "mode 2 names the kernel's target restriction: {}",
                    rec.reason
                );
            } else {
                assert!(
                    rec.reason.contains("泄露"),
                    "mode 1 keeps the user-readable-leak reason: {}",
                    rec.reason
                );
            }
        }
    }

    #[test]
    fn test_bpf_jit_enable() {
        let info = make_test_info();
        let mut recs = Vec::new();
        let checked = eval_bpf_jit_enable(&info, &mut recs);
        if std::path::Path::new("/proc/sys/net/core/bpf_jit_enable").exists() {
            assert!(checked >= 1);
        }
    }

    #[test]
    fn test_unprivileged_bpf_recommends_the_reversible_value() {
        // 1 and 2 both deny unprivileged bpf(), but the kernel will not clear a
        // 1 for the rest of the boot ("Once set to 1, this can't be cleared"),
        // so a 1 recommendation can never be rolled back. The rule is fed the
        // value directly so the assertion holds on a host that already reports
        // 1 or 2; the literal is asserted on purpose, so the rule cannot
        // silently regress to 1.
        let mut recs = Vec::new();
        recommend_unprivileged_bpf(0, "6.6.0", &mut recs);
        assert_eq!(recs.len(), 1, "0 must be recommended against");
        assert_eq!(
            recs[0].recommended_value, "2",
            "kernel.unprivileged_bpf_disabled must be recommended as 2: the kernel \
             cannot clear a 1, which would make the recommendation irreversible"
        );
        assert_eq!(recs[0].current_value, "0");
        assert_eq!(recs[0].category, Category::Security);
        assert_eq!(recs[0].confidence, Confidence::High);
        assert!(recs[0].writable);

        // Already denied: nothing to recommend, whichever way it was set.
        for current in [1u64, 2] {
            let mut recs = Vec::new();
            recommend_unprivileged_bpf(current, "6.6.0", &mut recs);
            assert!(
                recs.is_empty(),
                "unprivileged bpf is already denied by {current}, so there is \
                 nothing to change"
            );
        }
    }

    #[test]
    fn unprivileged_bpf_advice_needs_a_readable_switch() {
        // The rule fires on 0 — unprivileged bpf() allowed — and
        // read_sysctl_u64 maps an unreadable or unparseable file to that same
        // 0: a masked or garbled proc entry (a container's, typically) was
        // reported as `current_value: "0"` and answered with a write of 2 on a
        // host whose switch was never read.
        let (off, on, others) = zero_switch_paths("unprivileged_bpf_read", b"2\n");
        let mut info = make_test_info();
        info.kernel_version = "6.6.0".to_string();
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_unprivileged_bpf_at(&info, &mut recs, path.to_str().unwrap());
            recs
        };

        let recs = advice(&off);
        assert_eq!(recs.len(), 1, "a readable 0 allows unprivileged bpf()");
        assert_eq!(recs[0].current_value, "0");
        assert!(advice(&on).is_empty(), "a readable 2 denies it");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable switch is not 0",
                path.display()
            );
        }
    }

    #[test]
    fn test_unprivileged_bpf_old_kernels_get_no_advice() {
        // Through 5.12 the node only accepts the one-way 1: a write of 2 is
        // rejected with -EINVAL (proc_dointvec_minmax with
        // .extra1 = SYSCTL_ONE, .extra2 = SYSCTL_ONE) and a written 1 can
        // never be cleared, so there is no writable reversible value to
        // recommend.
        for version in ["4.19.91", "5.10.134", "5.12.19"] {
            let mut recs = Vec::new();
            recommend_unprivileged_bpf(0, version, &mut recs);
            assert!(
                recs.is_empty(),
                "{version} has no writable reversible value, so nothing may be advised"
            );
        }
        // 5.13 added the value 2 while keeping 0 and 1 writable, so the
        // reversible-value advice starts there.
        for version in ["5.13.0", "5.15.0-microsoft-standard-WSL2", "6.6.0"] {
            let mut recs = Vec::new();
            recommend_unprivileged_bpf(0, version, &mut recs);
            assert_eq!(recs.len(), 1, "{version} must still be advised the value 2");
            assert_eq!(recs[0].recommended_value, "2");
        }
    }

    /// The two sibling switches the rule consults before it may report a
    /// hardening gap, read exactly the way the rule reads them: a failed read
    /// fails open (it is not evidence that the switch is off).
    ///
    /// `bpf_jit_enable == 0` leaves every program's `jit_requested` false, so
    /// nothing can be blinded — unless the host listens, because the sibling
    /// rule raises a readable 0 to 1 in the same run; a non-zero
    /// `unprivileged_bpf_disabled` leaves only `bpf_capable()` loaders, and
    /// hardening level 1 does not blind those — and so does a 0 on 5.13+,
    /// where the rule's sibling writes 2 in the same plan. Either switch voids
    /// the advice, which is why the live assertion below has to model them.
    fn bpf_jit_harden_is_voided_by_a_switch(
        kernel_version: &str,
        has_listen_sockets: bool,
    ) -> bool {
        let switch = |path: &str| {
            std::fs::read_to_string(path)
                .ok()
                .map(|raw| raw.trim().to_string())
        };
        let unprivileged = switch("/proc/sys/kernel/unprivileged_bpf_disabled");
        (switch("/proc/sys/net/core/bpf_jit_enable").as_deref() == Some("0") && !has_listen_sockets)
            || unprivileged.as_deref().is_some_and(|value| value != "0")
            || (unprivileged.as_deref() == Some("0") && kernel_at_least(kernel_version, 5, 13))
    }

    #[test]
    fn test_bpf_jit_harden() {
        let info = make_test_info();
        let mut recs = Vec::new();
        let checked = eval_bpf_jit_harden(&info, &mut recs);
        assert_eq!(checked, 1);
        let triggered = recs.iter().any(|r| r.param == "net.core.bpf_jit_harden");
        // The sysctl is 0600 root-owned and its handler needs CAP_SYS_ADMIN,
        // so an unprivileged run cannot read it at all. Distinguish a
        // readable 0 (a finding) from a failed read (no value, no finding) —
        // read_sysctl_u64 maps the failure to 0 and cannot tell them apart.
        //
        // A readable 0 is a finding only while the rule's two sibling gates
        // leave the advice meaningful: with the JIT off or unprivileged BPF
        // denied the write would change nothing and the rule stays silent by
        // design (#6829), so the expectation has to follow. Without them this
        // assertion fails on every stock Ubuntu 24.04 host, where
        // `kernel.unprivileged_bpf_disabled` defaults to 2.
        let voided =
            bpf_jit_harden_is_voided_by_a_switch(&info.kernel_version, info.has_listen_sockets());
        match std::fs::read_to_string("/proc/sys/net/core/bpf_jit_harden") {
            Ok(raw) => {
                assert_eq!(
                    triggered,
                    raw.trim() == "0" && !voided,
                    "readable value {raw:?}, voided by a sibling switch: {voided}"
                );
                if triggered {
                    assert_eq!(recs.last().unwrap().category, Category::Security);
                }
            }
            Err(_) => assert!(
                !triggered,
                "an unreadable sysctl is not the value 0: {recs:?}"
            ),
        }
    }

    #[test]
    fn bpf_jit_harden_skips_an_unreadable_sysctl() {
        // A directory is the portable stand-in for "exists but cannot be
        // read" (EISDIR), which works for root and unprivileged runs alike.
        let info = make_test_info();
        let mut recs = Vec::new();
        assert_eq!(eval_bpf_jit_harden_at(&info, &mut recs, "/", "/", "/"), 1);
        assert!(
            recs.is_empty(),
            "a failed read must not report a hardening gap: {recs:?}"
        );
    }

    #[test]
    fn bpf_jit_harden_reads_real_values() {
        let info = make_test_info();
        let dir = std::env::temp_dir().join(format!("ktuner-bpf-harden-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("create temp dir");
        let path = dir.join("bpf_jit_harden");
        let path = path.to_str().expect("utf-8 temp path");
        let jit = dir.join("bpf_jit_enable");
        let jit = jit.to_str().expect("utf-8 temp path");
        let unprivileged = dir.join("unprivileged_bpf_disabled");
        let unprivileged = unprivileged.to_str().expect("utf-8 temp path");
        std::fs::write(jit, "1\n").expect("write fixture");
        std::fs::write(unprivileged, "0\n").expect("write fixture");

        std::fs::write(path, "0\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, path, jit, unprivileged);
        assert_eq!(recs.len(), 1, "a readable 0 is still a finding");
        assert_eq!(recs[0].param, "net.core.bpf_jit_harden");
        assert_eq!(recs[0].current_value, "0");
        assert_eq!(recs[0].recommended_value, "1");

        std::fs::write(path, "1\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, path, jit, unprivileged);
        assert!(recs.is_empty(), "a hardened host has no finding");

        // Garbage is a failed parse, not a value either.
        std::fs::write(path, "not-a-number\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, path, jit, unprivileged);
        assert!(recs.is_empty(), "unparseable content is not the value 0");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// The two switches that decide whether the recommended write has a
    /// consumer, and the fail-open rule for a switch that cannot be read.
    #[test]
    fn bpf_jit_harden_keeps_quiet_without_a_consumer() {
        let info = make_test_info();
        let dir = std::env::temp_dir().join(format!("ktuner-bpf-gates-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("create temp dir");
        let harden = dir.join("bpf_jit_harden");
        let harden = harden.to_str().expect("utf-8 temp path");
        let jit = dir.join("bpf_jit_enable");
        let jit = jit.to_str().expect("utf-8 temp path");
        let unprivileged = dir.join("unprivileged_bpf_disabled");
        let unprivileged = unprivileged.to_str().expect("utf-8 temp path");
        let absent = dir.join("absent");
        let absent = absent.to_str().expect("utf-8 temp path");
        std::fs::write(harden, "0\n").expect("write fixture");

        // Both switches leave a consumer: unprivileged loaders run JITed code
        // and level 1 blinds them.
        std::fs::write(jit, "1\n").expect("write fixture");
        std::fs::write(unprivileged, "0\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, jit, unprivileged);
        assert_eq!(recs.len(), 1, "a consumer exists: the gap is a finding");

        // JIT off on disk: not the state this run's plan leaves behind. The
        // sibling net.core.bpf_jit_enable rule raises a readable 0 to 1 on any
        // host that listens, so only a listener-less host keeps every program's
        // jit_requested false. The gate is a pure function of the two inputs,
        // so assert both shapes on it and let the `_at` form show the wiring
        // for whichever state the test host is in.
        assert!(
            !jit_in_force(Some(0), false),
            "no listener: the plan leaves the JIT off, nothing to blind"
        );
        assert!(
            jit_in_force(Some(0), true),
            "a listener gets the sibling rule's JIT enable in the same plan"
        );
        assert!(jit_in_force(Some(1), false), "a live JIT keeps the advice");
        assert!(
            jit_in_force(None, false),
            "an unreadable switch is not evidence that the JIT is off"
        );
        std::fs::write(jit, "0\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, jit, unprivileged);
        if info.has_listen_sockets() {
            assert_eq!(
                recs.len(),
                1,
                "the plan enables the JIT where the host listens: {recs:?}"
            );
        } else {
            assert!(
                recs.is_empty(),
                "no listener: the plan leaves the JIT off: {recs:?}"
            );
        }

        // Unprivileged BPF denied: every loader that can still load a program
        // is bpf_capable(), and level 1 does not blind those; level 2 denies
        // the unprivileged loaders outright.
        std::fs::write(jit, "1\n").expect("write fixture");
        std::fs::write(unprivileged, "1\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, jit, unprivileged);
        assert!(recs.is_empty(), "no unprivileged loader to blind");
        std::fs::write(unprivileged, "2\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, jit, unprivileged);
        assert!(recs.is_empty(), "level 2 denies unprivileged loads too");

        // Fail open: a switch that cannot be read, or is not there, is not
        // evidence that it is off.
        std::fs::write(unprivileged, "0\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, "/", unprivileged);
        assert_eq!(recs.len(), 1, "an unreadable jit switch keeps the advice");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, jit, "/");
        assert_eq!(
            recs.len(),
            1,
            "an unreadable unprivileged switch keeps the advice"
        );
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, absent, unprivileged);
        assert_eq!(recs.len(), 1, "a missing switch is not the value 0");

        // A readable 0 on 5.13+ is denied by this run's own plan: the sibling
        // unprivileged_bpf_disabled rule writes 2 out of it, which leaves no
        // non-capable loader for level-1 blinding, so the hardening entry the
        // same plan carries can never change a compiled program.
        let mut modern = make_test_info();
        modern.kernel_version = "6.6.0".to_string();
        std::fs::write(unprivileged, "0\n").expect("write fixture");
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&modern, &mut recs, harden, jit, unprivileged);
        assert!(
            recs.is_empty(),
            "the plan's own unprivileged_bpf_disabled = 2 removes the loader"
        );
        // Below 5.13 the value 2 does not exist, so the plan writes nothing
        // and the advice keeps the loader it has.
        let mut recs = Vec::new();
        eval_bpf_jit_harden_at(&info, &mut recs, harden, jit, unprivileged);
        assert_eq!(
            recs.len(),
            1,
            "no companion write exists below 5.13, so the advice stays"
        );

        std::fs::remove_file(harden).ok();
        std::fs::remove_file(jit).ok();
        std::fs::remove_file(unprivileged).ok();
        std::fs::remove_dir(&dir).ok();
    }

    #[test]
    fn promote_secondaries_advice_needs_a_readable_value() {
        // The rule fires on 0, and the reader mapped an unreadable or
        // unparseable file to the same 0: a masked or garbled proc entry (a
        // container's, typically) was reported as `current_value: "0"` and
        // answered with a write on a host whose value was never read.
        let (off, on, others) = zero_switch_paths("promote_secondaries_read", b"-1\n");
        let info = make_test_info();
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_promote_secondaries_at(&info, &mut recs, path.to_str().unwrap(), NO_ALL_SLOT);
            recs
        };

        let recs = advice(&off);
        assert_eq!(recs.len(), 1, "a readable 0 drops the secondaries");
        assert_eq!(recs[0].current_value, "0");
        assert!(advice(&on).is_empty(), "a readable -1 does not");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable value is not 0",
                path.display()
            );
        }
    }

    #[test]
    fn promote_secondaries_skips_a_default_all_already_covers() {
        // IN_DEV_PROMOTE_SECONDARIES ORs `conf/all` with the device slot, so
        // with `all` on every interface promotes and the `default` write
        // changes nothing; only an `all` read as 0 leaves the template in
        // force, and an unreadable one proves nothing.
        let (off, all_on, others) = zero_switch_paths("promote_secondaries_all", b"-1\n");
        let all_off = all_on.with_file_name("all_off");
        std::fs::write(&all_off, b"0\n").unwrap();
        let info = make_test_info();
        let advice = |all: &std::path::Path| {
            let mut recs = Vec::new();
            eval_promote_secondaries_at(
                &info,
                &mut recs,
                off.to_str().unwrap(),
                all.to_str().unwrap(),
            );
            recs.len()
        };

        assert_eq!(advice(&all_on), 0, "`all` already promotes everywhere");
        assert_eq!(advice(&all_off), 1, "`all` off leaves the template");
        assert_eq!(advice(&others[0]), 1, "an unreadable `all` is not on");
    }

    #[test]
    fn test_promote_secondaries() {
        // Synthetic slots only: the live rule now also reads `conf/all`, so a
        // host with `default=0, all=1` is correctly silent and a live-read
        // assertion would depend on the host.
        let (off, on, _) = zero_switch_paths("promote_secondaries_rule", b"1\n");
        let info = make_test_info();
        let advice = |path: &std::path::Path, all: &str| {
            let mut recs = Vec::new();
            let checked =
                eval_promote_secondaries_at(&info, &mut recs, path.to_str().unwrap(), all);
            assert_eq!(checked, 1);
            recs
        };

        let recs = advice(&off, NO_ALL_SLOT);
        assert_eq!(recs.len(), 1, "Should trigger when promote_secondaries=0");
        assert_eq!(recs[0].param, "net.ipv4.conf.default.promote_secondaries");
        assert_eq!(recs[0].recommended_value, "1");
        assert!(advice(&on, NO_ALL_SLOT).is_empty(), "1 is already on");
        assert!(
            advice(&off, on.to_str().unwrap()).is_empty(),
            "`all=1` covers a `default=0` template"
        );
    }

