    #[test]
    fn test_core_mem_max_reasons_name_the_explicit_buffer_cap() {
        // net.core.rmem_max/wmem_max bound an explicit setsockopt(SO_RCVBUF /
        // SO_SNDBUF) request (sock_setsockopt clamps it with sysctl_*mem_max),
        // while TCP's automatic tuning is capped by tcp_rmem[2] / tcp_wmem[2]
        // (tcp_rcv_space_adjust / tcp_sndbuf_expand). The core maxima cannot
        // unlock the triples, so the reason must not claim that they do.
        let mut info = make_test_info();
        info.network = vec![crate::detect::NetInfo {
            name: "eth0".to_string(),
            speed_mbps: 10000,
        }];
        let dir = std::env::temp_dir().join(format!(
            "ktuner_core_mem_max_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let rmem = dir.join("rmem_max");
        let wmem = dir.join("wmem_max");
        std::fs::write(&rmem, "212992\n").unwrap();
        std::fs::write(&wmem, "212992\n").unwrap();

        let mut recs = Vec::new();
        eval_rmem_max_at(&info, &mut recs, rmem.to_str().unwrap());
        eval_wmem_max_at(&info, &mut recs, wmem.to_str().unwrap());
        let r = recs
            .iter()
            .find(|r| r.param == "net.core.rmem_max")
            .expect("a 10G host under 16MB gets the recommendation");
        let w = recs
            .iter()
            .find(|r| r.param == "net.core.wmem_max")
            .expect("a 10G host under 16MB gets the recommendation");
        assert!(r.reason.contains("SO_RCVBUF"), "{}", r.reason);
        assert!(w.reason.contains("SO_SNDBUF"), "{}", w.reason);
        assert!(
            !r.reason.contains("tcp_rmem 的 max 值不会生效"),
            "{}",
            r.reason
        );
        assert!(
            !w.reason.contains("tcp_wmem 的 max 值不会生效"),
            "{}",
            w.reason
        );
    }

    #[test]
    fn test_core_mem_default_reasons_name_the_non_tcp_sockets() {
        // net.core.rmem_default/wmem_default only seed sk_rcvbuf/sk_sndbuf in
        // sock_init_data_uid(), and the non-TCP protocols queue against that
        // seed (__udp_enqueue_schedule_skb drops past sk_rcvbuf; the
        // __ip_append_data fragment path gives up past twice sk_sndbuf). A TCP
        // connection raises the seed to tcp_rmem[1] / tcp_wmem[1] in
        // tcp_init_sock(), so the reason must not describe a new connection's
        // buffer growth.
        let mut info = make_test_info();
        info.network = vec![crate::detect::NetInfo {
            name: "eth0".to_string(),
            speed_mbps: 10000,
        }];
        let dir = std::env::temp_dir().join(format!(
            "ktuner_core_mem_default_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let rmem = dir.join("rmem_default");
        let wmem = dir.join("wmem_default");
        std::fs::write(&rmem, "212992\n").unwrap();
        std::fs::write(&wmem, "212992\n").unwrap();

        let mut recs = Vec::new();
        eval_rmem_default_at(&info, &mut recs, rmem.to_str().unwrap());
        eval_wmem_default_at(&info, &mut recs, wmem.to_str().unwrap());
        let r = recs
            .iter()
            .find(|r| r.param == "net.core.rmem_default")
            .expect("a 10G host under 256K gets the recommendation");
        let w = recs
            .iter()
            .find(|r| r.param == "net.core.wmem_default")
            .expect("a 10G host under 256K gets the recommendation");
        assert!(r.reason.contains("非 TCP"), "{}", r.reason);
        assert!(w.reason.contains("非 TCP"), "{}", w.reason);
        assert!(r.reason.contains("tcp_rmem 的 default"), "{}", r.reason);
        assert!(w.reason.contains("tcp_wmem 的 default"), "{}", w.reason);
        assert!(
            !r.reason.contains("新建连接"),
            "a TCP connection never reads this knob: {}",
            r.reason
        );
        assert!(
            !w.reason.contains("新建连接"),
            "a TCP connection never reads this knob: {}",
            w.reason
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn test_ip_nonlocal_bind() {
        let info = make_test_info();
        let mut recs = Vec::new();
        let checked = eval_ip_nonlocal_bind(&info, &mut recs);
        if std::path::Path::new("/proc/sys/net/ipv4/ip_nonlocal_bind").exists() {
            assert_eq!(checked, 1);
            let val = read_sysctl_i64("/proc/sys/net/ipv4/ip_nonlocal_bind");
            if val != 0 {
                assert!(recs.iter().any(|r| r.param == "net.ipv4.ip_nonlocal_bind"));
                assert_eq!(recs.last().unwrap().category, Category::Security);
            }
        }
    }

    #[test]
    fn ip_nonlocal_bind_reads_truthiness_signed() {
        // Both registrations hold values the `== 1` comparison dropped: a
        // plain proc_dointvec int with no min/max through v5.12 (net/ipv4/
        // sysctl_net_ipv4.c, so -1 is legal), and a u8 proc_dou8vec_minmax
        // with no extra1/extra2 from v5.13 (0..=255). The only consumer is a
        // truthiness test (include/net/inet_sock.h `inet_can_nonlocal_bind()`
        // returns `READ_ONCE(net->ipv4.sysctl_ip_nonlocal_bind) || ...`), so
        // every non-zero value means "binding non-local addresses is on".
        let path =
            std::env::temp_dir().join(format!("ktuner-ip-nonlocal-bind-{}", std::process::id()));
        let path_str = path.to_str().unwrap();
        for (value, expect_rec) in [
            ("-1", true),
            ("0", false),
            ("1", true),
            ("2", true),
            ("255", true),
        ] {
            std::fs::write(&path, value).unwrap();
            let info = make_test_info();
            let mut recs = Vec::new();
            let checked = eval_ip_nonlocal_bind_at(&info, &mut recs, path_str, false);
            assert_eq!(checked, 1);
            let rec = recs.iter().find(|r| r.param == "net.ipv4.ip_nonlocal_bind");
            assert_eq!(
                rec.is_some(),
                expect_rec,
                "value={value}: 0 is the only off value"
            );
            if let Some(rec) = rec {
                assert_eq!(
                    rec.current_value, value,
                    "current must be what the kernel holds"
                );
                assert_eq!(rec.recommended_value, "0");
                assert_eq!(rec.category, Category::Security);
            }
        }
        // The VRRP gate still short-circuits: keepalived/HAProxy bind to
        // floating addresses on purpose.
        std::fs::write(&path, "1").unwrap();
        let info = make_test_info();
        let mut recs = Vec::new();
        eval_ip_nonlocal_bind_at(&info, &mut recs, path_str, true);
        assert!(
            recs.iter().all(|r| r.param != "net.ipv4.ip_nonlocal_bind"),
            "an HA host is not recommended to turn the bind off"
        );
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn icmp_ignore_bogus_reads_truthiness_signed() {
        // Same split registration as the tcp option bools: plain proc_dointvec
        // with no min/max through v5.12 (net/ipv4/sysctl_net_ipv4.c, -1 legal),
        // u8 proc_dou8vec_minmax from v5.13. icmp.c only tests truthiness
        // (`if (!READ_ONCE(...icmp_ignore_bogus_error_responses) && ...)`), so
        // the `== 0` gate is right — but the unsigned reader mapped -1 to 0 and
        // reported the finding on a host that ignores bogus responses already.
        let path =
            std::env::temp_dir().join(format!("ktuner-icmp-ignore-bogus-{}", std::process::id()));
        let path_str = path.to_str().unwrap();
        for (value, expect_rec) in [("-1", false), ("0", true), ("1", false), ("2", false)] {
            std::fs::write(&path, value).unwrap();
            let info = make_test_info();
            let mut recs = Vec::new();
            eval_icmp_ignore_bogus_at(&info, &mut recs, path_str);
            let rec = recs
                .iter()
                .find(|r| r.param == "net.ipv4.icmp_ignore_bogus_error_responses");
            assert_eq!(
                rec.is_some(),
                expect_rec,
                "value={value}: only 0 means the responses are not ignored"
            );
            if let Some(rec) = rec {
                assert_eq!(rec.current_value, "0");
                assert_eq!(rec.recommended_value, "1");
                assert_eq!(rec.category, Category::Security);
            }
        }
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn icmp_ignore_bogus_advice_needs_a_readable_switch() {
        // read_sysctl_i64 maps an unreadable or unparseable file to 0, the value
        // this gate fires on, so a masked or garbled proc entry (a
        // container's, typically) was reported as `current_value: "0"` and
        // answered with a write on a host whose switch was never read.
        let (off, on, others) = switch_fixture("icmp_bogus");
        let info = make_test_info();
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_icmp_ignore_bogus_at(&info, &mut recs, path.to_str().unwrap());
            recs
        };
        let recs = advice(&off);
        assert_eq!(recs.len(), 1, "a readable 0 logs bogus ICMP errors");
        assert_eq!(recs[0].current_value, "0");
        assert!(advice(&on).is_empty(), "a readable 1 ignores them");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable switch is not the value 0",
                path.display()
            );
        }
    }

