    #[test]
    fn test_panic_minus_one_reads_signed() {
        // `panic=-1` is the kernel's documented "reboot immediately, without
        // syncing" setting (kernel-parameters.txt; the sysctl is a plain
        // proc_dointvec int with no bounds). The unsigned reader parsed "-1"
        // to Err, fell back to 0 — the *never-reboot* value — so the rule
        // fired on exactly the most crash-resilient hosts and the
        // current_value it recorded, "0", is what a rollback would restore.
        let path = std::env::temp_dir().join(format!(
            "ktuner_panic_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::write(&path, b"-1\n").unwrap();
        let info = make_test_info();
        let mut recs = Vec::new();
        let checked = eval_panic_at(&info, &mut recs, path.to_str().unwrap());
        std::fs::remove_file(&path).ok();
        assert_eq!(checked, 1);
        assert!(
            recs.is_empty(),
            "-1 reboots immediately, so the host needs no recommendation: {recs:?}"
        );
    }

    #[test]
    fn test_panic_boundaries() {
        // 0 (loop forever after a panic) is the only unhardened value; a
        // positive timeout and the immediate-reboot -1 are already reboot
        // policies and must not be flagged.
        let info = make_test_info();
        for (value, expects_rec) in [(-1, false), (0, true), (10, false), (60, false)] {
            let path = std::env::temp_dir().join(format!(
                "ktuner_panic_bound_{}_{:?}_{}",
                std::process::id(),
                std::thread::current().id(),
                value
            ));
            std::fs::write(&path, format!("{value}\n")).unwrap();
            let mut recs = Vec::new();
            eval_panic_at(&info, &mut recs, path.to_str().unwrap());
            std::fs::remove_file(&path).ok();
            assert_eq!(
                recs.len(),
                usize::from(expects_rec),
                "value {value}: only 0 (never reboot) is unhardened"
            );
        }
    }

    #[test]
    fn test_panic_unreadable_switch_stays_quiet() {
        // The signed truthiness above is kept, and a file the reader cannot
        // interpret no longer becomes the value 0 these gates fire on: a
        // masked or garbled proc entry (a container's, typically) used to be
        // reported as `current_value: "0"` and answered with a write the host
        // may not need.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_panic_unreadable_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let malformed = dir.join("panic.malformed");
        std::fs::write(&malformed, b"never\n").unwrap();
        let empty = dir.join("panic.empty");
        std::fs::write(&empty, b"").unwrap();
        // A directory is an IO error even for root.
        let io_error = dir.join("panic.dir");
        std::fs::create_dir_all(&io_error).unwrap();
        let missing = dir.join("panic.missing");

        let info = make_test_info();
        for path in [&malformed, &empty, &io_error, &missing] {
            let mut recs = Vec::new();
            eval_panic_at(&info, &mut recs, path.to_str().unwrap());
            assert!(
                recs.is_empty(),
                "{}: an unreadable switch is not the value 0",
                path.display()
            );
        }

        // A readable 0 is still the unhardened value, and a readable -1 still
        // counts as enabled.
        for (value, expects_rec) in [("0", true), ("-1", false), ("1", false)] {
            let path = dir.join(format!("panic.{value}"));
            std::fs::write(&path, format!("{value}\n")).unwrap();
            let mut recs = Vec::new();
            eval_panic_at(&info, &mut recs, path.to_str().unwrap());
            assert_eq!(
                recs.len(),
                usize::from(expects_rec),
                "kernel.panic = {value}: only 0 is the unhardened value"
            );
        }
    }

