    /// `kernel.core_pattern` and `/proc/cmdline` are kernel text that carries
    /// whatever bytes the administrator or the boot loader wrote: a core
    /// directory or a `root=LABEL=` value that is not UTF-8 made the strict
    /// read fail, and each rule then fell back to its "unreadable" answer —
    /// the core_uses_pid advice despite a `%p` pattern, and no forced
    /// threading despite `threadirqs`.
    #[test]
    fn kernel_text_with_non_utf8_bytes_is_still_read() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_kernel_text_bytes_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let write = |name: &str, content: &[u8]| {
            let path = dir.join(name);
            std::fs::write(&path, content).unwrap();
            path
        };
        let param = write("core_uses_pid", b"0\n");
        let pattern = write("pattern-pid", b"/var/crash/\xff\xfe/core.%p\n");
        let mut recs = Vec::new();
        eval_core_uses_pid_at(
            &make_test_info(),
            &mut recs,
            param.to_str().unwrap(),
            pattern.to_str().unwrap(),
        );
        assert!(
            recs.is_empty(),
            "a %p pattern already records the pid, whatever its directory's bytes"
        );

        let cmdline = write(
            "cmdline",
            b"BOOT_IMAGE=/vmlinuz root=LABEL=\xc8\xed threadirqs quiet\n",
        );
        let version = write(
            "version",
            b"Linux version 6.6.0 (gcc) #1 SMP PREEMPT_DYNAMIC\n",
        );
        assert!(irqs_forced_threaded(
            cmdline.to_str().unwrap(),
            version.to_str().unwrap()
        ));

        std::fs::remove_dir_all(&dir).ok();
    }

    /// The forced-threading gate reads a second file, `/proc/version`, for the
    /// config flag a CONFIG_PREEMPT_RT build carries. That line is kernel text
    /// too: its `(user@host)` field is the build environment's `whoami`/
    /// `uname -n` bytes (`scripts/mkcompile_h`:9,14, or `KBUILD_BUILD_USER`/
    /// `KBUILD_BUILD_HOST`:11,16), and `version_proc_show` prints the banner
    /// through `seq_printf` (`fs/proc/version.c`), so one non-UTF-8 byte in the
    /// build host's name made the strict read fail and the rule advised an
    /// `rq_affinity` write the kernel ignores on an RT kernel.
    #[test]
    fn a_preempt_rt_banner_that_is_not_utf8_still_suppresses_the_advice() {
        let dir = std::env::temp_dir().join(format!(
            "ktuner_version_banner_bytes_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let cmdline = dir.join("cmdline");
        std::fs::write(&cmdline, "BOOT_IMAGE=/vmlinuz root=/dev/sda1\n").unwrap();
        let version = dir.join("version");
        std::fs::write(
            &version,
            b"Linux version 6.6.0 (kbuilder@b\xffuild) (gcc) #1 SMP PREEMPT_RT\n",
        )
        .unwrap();

        let mut info = make_test_info();
        info.numa_nodes = 2;
        info.disks[0].rq_affinity = Some(0);
        let mut recs = Vec::new();
        eval_rq_affinity_at(
            &info,
            &mut recs,
            cmdline.to_str().unwrap(),
            version.to_str().unwrap(),
        );
        assert!(
            !recs.iter().any(|r| r.param.contains("rq_affinity")),
            "a PREEMPT_RT kernel threads every handler, whatever the build host's bytes"
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn core_uses_pid_needs_a_core_pattern_that_leaves_it_something_to_do() {
        // fs/coredump.c appends the compatibility `.PID` only under
        // "if (!ispipe && !pid_in_pattern && core_uses_pid)": a piped pattern
        // (systemd-coredump) never reaches the filename logic, and a pattern
        // carrying its own %p already records the pid. On those hosts the
        // reason's promise is already met, so the rule must stay quiet.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_core_uses_pid_pattern_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let write = |name: &str, content: &str| {
            let path = dir.join(name);
            std::fs::write(&path, content).unwrap();
            path
        };
        let param = write("core_uses_pid", "0\n");
        let plain = write("pattern-plain", "core\n");
        // A literal %p written with an escape: the kernel emits "%p" as text
        // and still appends .PID, so the knob keeps its job.
        let escaped = write("pattern-escaped", "core.%%p\n");
        let with_pid = write("pattern-pid", "core.%p\n");
        let piped = write(
            "pattern-pipe",
            "|/usr/lib/systemd/systemd-coredump %P %u %g %s %t %c %h\n",
        );
        let missing = dir.join("pattern-missing");

        let info = make_test_info();

        for pattern in [&with_pid, &piped] {
            let mut recs = Vec::new();
            eval_core_uses_pid_at(
                &info,
                &mut recs,
                param.to_str().unwrap(),
                pattern.to_str().unwrap(),
            );
            assert!(
                recs.is_empty(),
                "{}: the kernel already records the pid",
                pattern.display()
            );
        }

        for pattern in [&plain, &escaped, &missing] {
            let mut recs = Vec::new();
            eval_core_uses_pid_at(
                &info,
                &mut recs,
                param.to_str().unwrap(),
                pattern.to_str().unwrap(),
            );
            assert!(
                recs.iter().any(|r| r.param == "kernel.core_uses_pid"),
                "{}: the knob still names the core file",
                pattern.display()
            );
        }

        std::fs::remove_dir_all(&dir).ok();
    }

