    #[test]
    fn test_oom_dump_unreadable_switch_stays_quiet() {
        // The signed truthiness above is kept, and a file the reader cannot
        // interpret no longer becomes the value 0 these gates fire on: a
        // masked or garbled proc entry (a container's, typically) used to be
        // reported as `current_value: "0"` and answered with a write the host
        // may not need.
        let dir = std::env::temp_dir().join(format!(
            "ktuner_oom_dump_unreadable_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let malformed = dir.join("oom_dump.malformed");
        std::fs::write(&malformed, b"never\n").unwrap();
        let empty = dir.join("oom_dump.empty");
        std::fs::write(&empty, b"").unwrap();
        // A directory is an IO error even for root.
        let io_error = dir.join("oom_dump.dir");
        std::fs::create_dir_all(&io_error).unwrap();
        let missing = dir.join("oom_dump.missing");

        let info = make_test_info();
        for path in [&malformed, &empty, &io_error, &missing] {
            let mut recs = Vec::new();
            eval_oom_dump_tasks_at(&info, &mut recs, path.to_str().unwrap());
            assert!(
                recs.is_empty(),
                "{}: an unreadable switch is not the value 0",
                path.display()
            );
        }

        // A readable 0 is still the unhardened value, and a readable -1 still
        // counts as enabled.
        for (value, expects_rec) in [("0", true), ("-1", false), ("1", false)] {
            let path = dir.join(format!("oom_dump.{value}"));
            std::fs::write(&path, format!("{value}\n")).unwrap();
            let mut recs = Vec::new();
            eval_oom_dump_tasks_at(&info, &mut recs, path.to_str().unwrap());
            assert_eq!(
                recs.len(),
                usize::from(expects_rec),
                "vm.oom_dump_tasks = {value}: only 0 is the unhardened value"
            );
        }
    }

    #[test]
    fn test_log_martians_reads_truthiness_signed() {
        // net/ipv4/devinet.c's devinet_conf_proc routes this entry through a
        // plain proc_dointvec on an int slot (no min/max), and
        // IN_DEV_LOG_MARTIANS (include/linux/inetdevice.h) reads it through
        // IN_DEV_ORCONF, a truthiness test consumed by net/ipv4/route.c. Any
        // nonzero value is enabled, so -1 must not read as the value 0.
        let info = make_test_info();
        for (value, expects_rec) in [(-1, false), (0, true), (1, false)] {
            let path = std::env::temp_dir().join(format!(
                "ktuner_log_martians_{}_{:?}_{value}",
                std::process::id(),
                std::thread::current().id()
            ));
            std::fs::write(&path, format!("{value}\n")).unwrap();
            let mut recs = Vec::new();
            let checked = eval_log_martians_at(&info, &mut recs, path.to_str().unwrap());
            std::fs::remove_file(&path).ok();
            assert_eq!(checked, 1);
            assert_eq!(
                recs.len(),
                usize::from(expects_rec),
                "value {value}: only 0 leaves martians unlogged"
            );
            if expects_rec {
                assert_eq!(recs[0].param, "net.ipv4.conf.all.log_martians");
                assert_eq!(recs[0].current_value, "0");
                assert_eq!(recs[0].recommended_value, "1");
            }
        }
    }

    #[test]
    fn log_martians_advice_needs_a_readable_switch() {
        // read_sysctl_i64 maps an unreadable or unparseable file to 0, the value
        // this gate fires on, so a masked or garbled proc entry (a
        // container's, typically) was reported as `current_value: "0"` and
        // answered with a write on a host whose switch was never read.
        let (off, on, others) = switch_fixture("log_martians");
        let info = make_test_info();
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_log_martians_at(&info, &mut recs, path.to_str().unwrap());
            recs
        };
        let recs = advice(&off);
        assert_eq!(recs.len(), 1, "a readable 0 drops martians silently");
        assert_eq!(recs[0].current_value, "0");
        assert!(advice(&on).is_empty(), "a readable 1 logs them");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable switch is not the value 0",
                path.display()
            );
        }
    }

