    #[test]
    fn test_secure_redirects_reads_truthiness_signed() {
        // The gate is `!= 0`, so the unsigned reader's collapse of -1 to 0
        // silently skipped the rule on a host whose secure redirects are on
        // (IN_DEV_SEC_REDIRECTS is an ORCONF truthiness test).
        let info = make_test_info();
        let conf = std::env::temp_dir().join(format!(
            "ktuner_secure_redirects_conf_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&conf);
        for relative in ["all/shared_media", "eth0/shared_media"] {
            let path = conf.join(relative);
            std::fs::create_dir_all(path.parent().expect("parent")).unwrap();
            // Shared media off so the shared_media gate keeps the knob
            // reachable and this test still observes the signed read.
            std::fs::write(&path, "0\n").unwrap();
        }
        for (value, expects_rec) in [(-1, true), (0, false), (1, true)] {
            let path = std::env::temp_dir().join(format!(
                "ktuner_secure_redirects_{}_{:?}_{value}",
                std::process::id(),
                std::thread::current().id()
            ));
            std::fs::write(&path, format!("{value}\n")).unwrap();
            let mut recs = Vec::new();
            let checked = eval_secure_redirects_at(&info, &mut recs, path.to_str().unwrap(), &conf);
            std::fs::remove_file(&path).ok();
            assert_eq!(checked, 1);
            assert_eq!(
                recs.len(),
                usize::from(expects_rec),
                "value {value}: any nonzero value accepts secure redirects"
            );
            if expects_rec {
                assert_eq!(recs[0].param, "net.ipv4.conf.all.secure_redirects");
                assert_eq!(
                    recs[0].current_value,
                    value.to_string(),
                    "current_value must echo the signed value verbatim"
                );
                assert_eq!(recs[0].recommended_value, "0");
            }
        }
    }

    #[test]
    fn secure_redirects_advice_needs_shared_media_off() {
        // __ip_do_redirect() (net/ipv4/route.c) reads IN_DEV_SEC_REDIRECTS only
        // inside its `if (!IN_DEV_SHARED_MEDIA(in_dev))` branch, and the sysctl
        // documentation states the override outright — "shared_media ...
        // Overrides secure_redirects" / "Overridden by shared_media". Shared
        // media defaults to on and IN_DEV_SHARED_MEDIA is an OR of conf/all
        // and the device value, so the default host never reaches the branch
        // and writing secure_redirects cannot change how a redirect is judged.
        let info = make_test_info();
        let dir = std::env::temp_dir().join(format!(
            "ktuner_secure_redirects_media_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let write = |relative: &str, content: &str| {
            let path = dir.join(relative);
            std::fs::create_dir_all(path.parent().expect("parent")).unwrap();
            std::fs::write(&path, content).unwrap();
            path
        };
        let knob = write("all/secure_redirects", "1\n");
        for interface in ["default", "lo", "eth0"] {
            write(&format!("{interface}/shared_media"), "0\n");
        }

        // conf/all keeps shared media on for every interface (ORCONF), so the
        // per-device zero cannot make secure_redirects reachable.
        write("all/shared_media", "1\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert!(
            recs.is_empty(),
            "no redirect is judged by secure_redirects while shared media is on"
        );

        // Both halves off on one interface: the kernel reads the knob again.
        write("all/shared_media", "0\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(
            recs.len(),
            1,
            "one interface with shared media off makes the write reachable"
        );
        assert_eq!(recs[0].param, "net.ipv4.conf.all.secure_redirects");

        // Every device back on the default leaves nothing reading the knob,
        // even with conf/all off.
        for interface in ["default", "lo", "eth0"] {
            write(&format!("{interface}/shared_media"), "1\n");
        }
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert!(
            recs.is_empty(),
            "no interface reads secure_redirects once shared media is back on"
        );
    }

    #[test]
    fn secure_redirects_advice_needs_an_accepting_interface() {
        // The knob has a second precondition in front of its consumer:
        // __ip_do_redirect() (net/ipv4/route.c) rejects the redirect on
        // !IN_DEV_RX_REDIRECTS(in_dev) (v6.6 :768, 7.3-rc6 :803) before its
        // IN_DEV_SEC_REDIRECTS line (v6.6 :776, 7.3-rc6 :811) runs, and
        // IN_DEV_RX_REDIRECTS (include/linux/inetdevice.h) is the interface
        // accept_redirects slot. With every accept_redirects value at zero no
        // redirect is ever judged, so the write cannot change anything and
        // the rule must stay quiet.
        let info = make_test_info();
        let dir = std::env::temp_dir().join(format!(
            "ktuner_secure_redirects_accept_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let write = |relative: &str, content: &str| {
            let path = dir.join(relative);
            std::fs::create_dir_all(path.parent().expect("parent")).unwrap();
            std::fs::write(&path, content).unwrap();
            path
        };
        let knob = write("all/secure_redirects", "1\n");
        // The shared-media gate sits ahead of this one; both have to be open
        // before the rule can speak at all.
        for relative in ["all/shared_media", "eth0/shared_media"] {
            write(relative, "0\n");
        }

        // Every accept_redirects slot at zero: nothing reaches the consumer.
        write("all/accept_redirects", "0\n");
        write("eth0/accept_redirects", "0\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert!(
            recs.is_empty(),
            "no redirect is judged by secure_redirects while accept_redirects is off everywhere"
        );

        // The interface's own slot back on: the redirect reaches the test.
        write("eth0/accept_redirects", "1\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(
            recs.len(),
            1,
            "one interface accepting redirects keeps the write relevant"
        );

        // The `all` template alone is enough for a non-forwarding interface,
        // where the kernel ORs the two slots.
        write("eth0/accept_redirects", "0\n");
        write("all/accept_redirects", "1\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(recs.len(), 1, "conf/all accepting reaches every interface");

        // `default` seeds interfaces created later, so the zero is only
        // proven to cover them when it is zero there too.
        write("all/accept_redirects", "0\n");
        write("default/accept_redirects", "1\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(
            recs.len(),
            1,
            "the default template can accept on a future interface"
        );

        // A slot that cannot be read is not evidence of a zero.
        write("default/accept_redirects", "0\n");
        write("eth0/accept_redirects", "masked\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(
            recs.len(),
            1,
            "an unreadable slot keeps the advice instead of guessing a zero"
        );
    }

    #[test]
    fn secure_redirects_ignores_an_accepting_forwarding_interface() {
        // IN_DEV_RX_REDIRECTS is not one expression: a FORWARDING interface
        // ANDs `conf/all` with its own accept_redirects slot, a non-forwarding
        // one ORs them (v6.6 include/linux/inetdevice.h:124-128), and
        // IN_DEV_FORWARD reads the device's own `forwarding` slot. With `all`
        // already read as zero, a forwarding interface's own slot cannot turn
        // the test back on, so it is not evidence that a redirect reaches the
        // secure-redirects line: the write is inert there and the advice must
        // be skipped.
        let info = make_test_info();
        let dir = std::env::temp_dir().join(format!(
            "ktuner_secure_redirects_fwd_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let write = |relative: &str, content: &str| {
            let path = dir.join(relative);
            std::fs::create_dir_all(path.parent().expect("parent")).unwrap();
            std::fs::write(&path, content).unwrap();
            path
        };
        let knob = write("all/secure_redirects", "1\n");
        // The shared-media gate sits ahead of this one; both have to be open
        // before the rule can speak at all.
        for relative in ["all/shared_media", "eth0/shared_media"] {
            write(relative, "0\n");
        }
        write("all/accept_redirects", "0\n");
        write("eth0/accept_redirects", "1\n");

        // The interface forwards, and `all` is zero: the AND half is false
        // whatever the device slot says.
        write("eth0/forwarding", "1\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert!(
            recs.is_empty(),
            "a forwarding interface cannot reach the test with `all` off"
        );

        // The same slot on a non-forwarding interface is read through the OR
        // half, so the redirect does reach the test.
        write("eth0/forwarding", "0\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(
            recs.len(),
            1,
            "a non-forwarding interface accepting through the OR half keeps the advice"
        );

        // A bypass is decided per interface: one forwarding interface that
        // accepts does not cover a second, non-forwarding one that does.
        write("eth0/forwarding", "1\n");
        write("eth1/accept_redirects", "1\n");
        write("eth1/forwarding", "0\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(
            recs.len(),
            1,
            "one interface that really accepts keeps the write relevant"
        );
        std::fs::remove_dir_all(dir.join("eth1")).ok();

        // A `forwarding` slot that cannot be read proves nothing either way.
        write("eth0/forwarding", "masked\n");
        let mut recs = Vec::new();
        eval_secure_redirects_at(&info, &mut recs, knob.to_str().unwrap(), &dir);
        assert_eq!(
            recs.len(),
            1,
            "an unreadable forwarding slot keeps the advice instead of guessing the exemption"
        );
    }

    #[test]
    fn default_secure_redirects_covers_the_template_all_leaves_behind() {
        // IN_DEV_SEC_REDIRECTS is an ORCONF of the `all` slot and the device's
        // own (v6.6 include/linux/inetdevice.h:91-92, 113-114), so writing
        // `all` to 0 leaves every interface that still carries the template's
        // inherited 1 accepting redirects to its default gateways. The `all`
        // rule's own plan is therefore half a fix, and this rule names the
        // template slot the devices inherit.
        let info = make_test_info();
        let dir = std::env::temp_dir().join(format!(
            "ktuner_default_secure_redirects_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let write = |relative: &str, content: &str| {
            let path = dir.join(relative);
            std::fs::create_dir_all(path.parent().expect("parent")).unwrap();
            std::fs::write(&path, content).unwrap();
            path
        };
        let template = write("default/secure_redirects", "1\n");
        // Both preconditions open: one interface has shared media off, and an
        // interface accepts redirects through the OR half.
        for relative in ["all/shared_media", "eth0/shared_media"] {
            write(relative, "0\n");
        }
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_default_secure_redirects_at(&info, &mut recs, path.to_str().unwrap(), &dir);
            recs
        };

        let recs = advice(&template);
        assert_eq!(recs.len(), 1, "the template still arms future interfaces");
        assert_eq!(recs[0].param, "net.ipv4.conf.default.secure_redirects");
        assert_eq!(recs[0].current_value, "1");
        assert_eq!(recs[0].recommended_value, "0");
        assert_eq!(recs[0].category, Category::Security);

        // A readable 0 template needs nothing; -1 is legal and armed.
        let zero = write("default/secure_redirects.0", "0\n");
        assert!(advice(&zero).is_empty(), "a 0 template is already off");
        let negative = write("default/secure_redirects.neg", "-1\n");
        let armed = advice(&negative);
        assert_eq!(armed.len(), 1, "-1 is legal in this plain int slot");
        assert_eq!(armed[0].current_value, "-1");

        // An unreadable template is not evidence of an armed one.
        let garbled = write("default/secure_redirects.garbled", "masked\n");
        assert!(advice(&garbled).is_empty(), "a garbled slot proves nothing");
        assert!(
            advice(std::path::Path::new(
                "/nonexistent/ktuner/default_secure_redirects"
            ))
            .is_empty(),
            "a missing slot proves nothing"
        );
    }

    #[test]
    fn default_secure_redirects_keeps_the_shared_media_and_accept_gates() {
        // The new template rule reads the same consumer as the `all` rule, so
        // it must inherit both preconditions: while shared media is on for
        // every interface, or no interface accepts redirects at all,
        // __ip_do_redirect() never consults IN_DEV_SEC_REDIRECTS and the
        // template write changes nothing.
        let info = make_test_info();
        let dir = std::env::temp_dir().join(format!(
            "ktuner_default_secure_redirects_gates_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let write = |relative: &str, content: &str| {
            let path = dir.join(relative);
            std::fs::create_dir_all(path.parent().expect("parent")).unwrap();
            std::fs::write(&path, content).unwrap();
            path
        };
        let template = write("default/secure_redirects", "1\n");
        let advice = |dir: &std::path::Path| {
            let mut recs = Vec::new();
            eval_default_secure_redirects_at(&info, &mut recs, template.to_str().unwrap(), dir);
            recs.len()
        };

        // Shared media on everywhere: the knob has no reader.
        for relative in ["all/shared_media", "eth0/shared_media"] {
            write(relative, "1\n");
        }
        assert_eq!(advice(&dir), 0, "shared media on everywhere hides the knob");

        // Shared media off, but every accept_redirects reads 0: the earlier
        // bail-out wins and the knob is still unreachable.
        for relative in ["all/shared_media", "eth0/shared_media"] {
            write(relative, "0\n");
        }
        write("all/accept_redirects", "0\n");
        for interface in ["default", "eth0"] {
            write(&format!("{interface}/accept_redirects"), "0\n");
        }
        assert_eq!(advice(&dir), 0, "no interface accepts a redirect at all");

        // One interface accepting through the OR half opens the consumer.
        write("eth0/accept_redirects", "1\n");
        assert_eq!(advice(&dir), 1, "an accepting interface keeps the advice");
    }

    #[test]
    fn test_arp_filter_reads_truthiness_signed() {
        // devinet_conf_proc int slot; IN_DEV_ARPFILTER is an ORCONF
        // truthiness test consumed by net/ipv4/arp.c. The multi-NIC gate
        // needs two interfaces and no bond on the host, so the 0 case is
        // asserted only when that gate lets the rule run.
        let mut info = make_test_info();
        info.network = vec![
            NetInfo {
                name: "eth0".to_string(),
                speed_mbps: 10000,
            },
            NetInfo {
                name: "eth1".to_string(),
                speed_mbps: 10000,
            },
        ];
        let bonded = has_bond();
        for (value, expects_rec) in [(-1, false), (0, !bonded), (1, false)] {
            let path = std::env::temp_dir().join(format!(
                "ktuner_arp_filter_{}_{:?}_{value}",
                std::process::id(),
                std::thread::current().id()
            ));
            std::fs::write(&path, format!("{value}\n")).unwrap();
            let mut recs = Vec::new();
            let checked = eval_arp_filter_at(&info, &mut recs, path.to_str().unwrap());
            std::fs::remove_file(&path).ok();
            assert_eq!(checked, 1);
            assert_eq!(
                recs.len(),
                usize::from(expects_rec),
                "value {value}: only 0 leaves multi-NIC ARP unfiltered"
            );
            if expects_rec {
                assert_eq!(recs[0].param, "net.ipv4.conf.all.arp_filter");
                assert_eq!(recs[0].current_value, "0");
                assert_eq!(recs[0].recommended_value, "1");
            }
        }
    }

    #[test]
    fn arp_filter_advice_needs_a_readable_switch() {
        // read_sysctl_i64 maps an unreadable or unparseable file to 0, the value
        // this gate fires on, so a masked or garbled proc entry (a
        // container's, typically) was reported as `current_value: "0"` and
        // answered with a write on a host whose switch was never read. The
        // multi-NIC gate needs two interfaces and no bond, so the 0 case is
        // asserted only when that gate lets the rule run.
        let (off, on, others) = switch_fixture("arp_filter");
        let mut info = make_test_info();
        info.network = vec![
            NetInfo {
                name: "eth0".to_string(),
                speed_mbps: 10000,
            },
            NetInfo {
                name: "eth1".to_string(),
                speed_mbps: 10000,
            },
        ];
        let advice = |path: &std::path::Path| {
            let mut recs = Vec::new();
            eval_arp_filter_at(&info, &mut recs, path.to_str().unwrap());
            recs
        };
        assert_eq!(
            advice(&off).len(),
            usize::from(!has_bond()),
            "a readable 0 leaves multi-NIC ARP unfiltered"
        );
        assert!(advice(&on).is_empty(), "a readable 1 filters it");
        for path in &others {
            assert!(
                advice(path).is_empty(),
                "{}: an unreadable switch is not the value 0",
                path.display()
            );
        }
    }

    #[test]
    fn tcp_option_bools_read_truthiness_signed() {
        // tcp_window_scaling, tcp_sack and tcp_timestamps were all plain
        // proc_dointvec ints with no min/max through v5.10 (net/ipv4/
        // sysctl_net_ipv4.c), so "-1" is a legal, persistent value, and
        // every kernel consumer is a truthiness test (tcp_output.c / tcp_input.c
        // arm the window-scale, SACK-perm and timestamp SYN options with a
        // bare READ_ONCE). The unsigned reader parsed "-1" to Err and fell
        // back to 0, the *disabled* value, so all three `== 0` gates
        // invented a finding on hosts that already run the option.
        let info = make_test_info();
        for (value, expects_rec) in [(-1, false), (0, true), (1, false), (2, false)] {
            let path = std::env::temp_dir().join(format!(
                "ktuner_tcp_opt_bool_{}_{:?}_{value}",
                std::process::id(),
                std::thread::current().id()
            ));
            std::fs::write(&path, format!("{value}\n")).unwrap();
            let mut recs = Vec::new();
            let checked_ws = eval_tcp_window_scaling_at(&info, &mut recs, path.to_str().unwrap());
            let mut sack_recs = Vec::new();
            let checked_sack = eval_tcp_sack_at(&info, &mut sack_recs, path.to_str().unwrap());
            let mut ts_recs = Vec::new();
            let checked_ts = eval_tcp_timestamps_at(&info, &mut ts_recs, path.to_str().unwrap());
            std::fs::remove_file(&path).ok();
            assert_eq!(checked_ws, 1);
            assert_eq!(checked_sack, 1);
            assert_eq!(checked_ts, 1);
            for (label, recs) in [
                ("window_scaling", &recs),
                ("sack", &sack_recs),
                ("timestamps", &ts_recs),
            ] {
                assert_eq!(
                    recs.len(),
                    usize::from(expects_rec),
                    "{label} value {value}: only 0 disables the option"
                );
            }
            if expects_rec {
                assert_eq!(recs[0].param, "net.ipv4.tcp_window_scaling");
                assert_eq!(sack_recs[0].param, "net.ipv4.tcp_sack");
                assert_eq!(ts_recs[0].param, "net.ipv4.tcp_timestamps");
                assert_eq!(recs[0].recommended_value, "1");
            }
        }
    }

